/* Katalog API Slak 1.9.1: dibuat dari Referensi dan contoh API Slak Studio. Satu entri per fungsi. */
window.SLAK_KATALOG = [{"g":"Teks","n":"title","sig":"title(teks)","d":"Judul besar halaman.","k":"sl.title(\"Laporan Penjualan :bar_chart:\")\nsl.caption(\"Judul utama halaman. Arahkan kursor ke judul untuk tautan #.\")"},{"g":"Teks","n":"header","sig":"header(teks, {divider, anchor})","d":"Judul bagian. `divider: true` atau nama warna menambah garis bawah. Arahkan kursor untuk tautan #; `anchor: false` mematikannya.","k":"sl.header(\"Ringkasan\", { divider: \"blue\" })\nsl.write(\"Isi bagian ringkasan.\")"},{"g":"Teks","n":"subheader","sig":"subheader(teks)","d":"Judul sub-bagian.","k":"sl.subheader(\"Omzet per kota\", { divider: true })\nsl.write(\"Jayapura memimpin bulan ini.\")"},{"g":"Teks","n":"markdown","sig":"markdown(teks, {unsafe_allow_html})","d":"Teks Markdown: **tebal**, *miring*, `kode`, daftar, tabel, kutipan, tautan, warna `:red[teks]`, latar `:blue-background[teks]`, lencana `:green-badge[teks]`, ikon `:material/home:`, dan rumus `$E=mc^2$` atau `$$...$$`. Emoji bisa ditulis dengan nama: `:smile:`, `:kantung_uang:`, `:uang:`.","k":"sl.markdown(`\n**Tebal**, *miring*, \\`kode\\`, :red[merah], :blue-background[latar biru], :green-badge[lencana]\n\n- Daftar berpoin :white_check_mark:\n- Tautan ke [Slak](https://example.com)\n\n| Kota | Omzet |\n|---|---|\n| Jayapura | 12 jt |\n`)"},{"g":"Teks","n":"write","sig":"write(...nilai)","d":"Serbaguna. Teks jadi Markdown, larik objek jadi tabel, objek jadi JSON, Error jadi kotak galat.","k":"sl.write(\"Teks **Markdown** biasa\")\nsl.write(42, \"adalah jawaban\")\nsl.write({ kota: \"Jayapura\", omzet: 12500000 })\nsl.write(sl.dataset(\"iris\").head(3))"},{"g":"Teks","n":"caption","sig":"caption(teks)","d":"Teks kecil berwarna redup.","k":"sl.metric(\"Omzet\", \"Rp 12,5 jt\")\nsl.caption(\"Sumber: data penjualan internal, diperbarui tiap Senin.\")"},{"g":"Teks","n":"text","sig":"text(teks)","d":"Teks polos berhuruf monospace, tanpa Markdown.","k":"sl.text(\"Teks polos: **tidak** diubah menjadi tebal.\")"},{"g":"Teks","n":"code","sig":"code(kode, bahasa)","d":"Blok kode dengan tombol salin.","k":"sl.code(`const df = sl.dataset(\"penjualan\")\nsl.bar_chart(df.groupby(\"kota\").agg({ omzet: [\"total\", \"sum\"] }), { x: \"kota\", y: \"omzet\" })`, \"javascript\")"},{"g":"Teks","n":"json","sig":"json(objek)","d":"Menampilkan objek sebagai JSON berwarna.","k":"sl.json({ nama: \"Toko Maju\", kota: [\"Jayapura\", \"Sorong\"], aktif: true, pemilik: { nama: \"Ani\" } })"},{"g":"Teks","n":"html","sig":"html(string)","d":"Menyisipkan HTML mentah.","k":"sl.html('<div style=\"padding:12px;border-radius:10px;background:#ecfdf5;color:#065f46\">Kotak <b>HTML</b> sendiri</div>')"},{"g":"Teks","n":"divider","sig":"divider()","d":"Garis pemisah horizontal.","k":"sl.write(\"Bagian atas\")\nsl.divider()\nsl.write(\"Bagian bawah\")"},{"g":"Status","n":"success","sig":"success(teks)","d":"Kotak pesan hijau.","k":"sl.success(\"Data berhasil disimpan.\", { icon: \":white_check_mark:\" })"},{"g":"Status","n":"info","sig":"info(teks)","d":"Kotak pesan biru.","k":"sl.info(\"Data diperbarui setiap Senin pagi.\", { icon: \":information_source:\" })"},{"g":"Status","n":"warning","sig":"warning(teks)","d":"Kotak pesan kuning.","k":"sl.warning(\"Stok 3 barang di bawah batas minimum.\")"},{"g":"Status","n":"error","sig":"error(teks)","d":"Kotak pesan merah.","k":"sl.error(\"Berkas tidak bisa dibaca. Periksa formatnya.\")"},{"g":"Status","n":"exception","sig":"exception(err)","d":"Menampilkan objek Error beserta stack trace.","k":"try {\n  JSON.parse(\"{rusak\")\n} catch (e) {\n  sl.exception(e)\n}"},{"g":"Status","n":"progress","sig":"progress(nilai0sd100, teks)","d":"Bilah kemajuan. Kembalikan objek dengan `.progress(nilai, teks)` untuk diperbarui.","k":"const p = sl.progress(0, \"Memproses…\")\nfor (let i = 0; i <= 100; i += 25) {\n  p.progress(i, `Memproses… ${i}%`)\n  await sl.sleep(200)\n}"},{"g":"Status","n":"spinner","sig":"await spinner(teks, fungsiAsync)","d":"Menampilkan pemutar selama fungsi berjalan.","k":"await sl.spinner(\"Menghitung…\", () => sl.sleep(800))\nsl.success(\"Selesai!\")"},{"g":"Status","n":"toast","sig":"toast(teks, ikon)","d":"Notifikasi kecil yang hilang sendiri.","k":"if (sl.button(\"Simpan\")) sl.toast(\"Tersimpan :tada:\", { icon: \":white_check_mark:\" })"},{"g":"Status","n":"balloons","sig":"balloons()","d":"Animasi balon perayaan.","k":"if (sl.button(\"Rayakan :partying_face:\")) sl.balloons()"},{"g":"Data","n":"dataframe","sig":"dataframe(data, {height, width, hide_index, column_order, column_config, on_select, selection_mode, row_height, placeholder, format, gradient})","d":"Tabel interaktif: urutkan, cari (⌕), unduh CSV. `column_config` mengatur jenis kolom (progress, tautan, gambar, grafik mini…). Dengan `on_select: \"rerun\"` baris/kolom/sel bisa dipilih dan hasilnya `{selection: {rows, columns, cells}}`.","k":"const df = sl.dataset(\"penjualan\")\nsl.dataframe(df.head(50), {\n  hide_index: true,\n  column_config: { total: sl.column_config.NumberColumn(\"Total\", { format: \"rp\" }) }\n})"},{"g":"Data","n":"table","sig":"table(data)","d":"Tabel statis.","k":"const df = sl.dataset(\"penjualan\").groupby(\"kota\").agg({ omzet: [\"total\", \"sum\"] })\nsl.table(df)"},{"g":"Data","n":"metric","sig":"metric(label, nilai, delta, {delta_color, format, chart_data, chart_type, delta_arrow, delta_description, icon, border, help})","d":"Angka besar dengan perubahan. `chart_data` menambah grafik mini (line/area/bar). `format`: \"dollar\", \"percent\", \"compact\", \"rp\", atau printf seperti \"%.1f\". `delta_color`: normal, inverse, off, atau nama warna.","k":"const [a, b, c] = sl.columns(3)\na.metric(\"Omzet\", \"Rp 210 jt\", \"+12%\", { border: true })\nb.metric(\"Transaksi\", \"1.520\", \"-3%\", { border: true })\nc.metric(\"Retur\", \"18\", \"-5\", { delta_color: \"inverse\", border: true, chart_data: [5, 8, 6, 9, 7, 4] })"},{"g":"Grafik","n":"line_chart","sig":"line_chart(data, {x, y, height, title, x_label, y_label, color})","d":"Grafik garis. `y` bisa satu nama kolom atau larik. Dengan `on_select: \"rerun\"`, klik titik mengembalikan `{selection: {points, rows}}`.","k":"const df = sl.dataset(\"penjualan\")\nconst bulanan = df.assign({ bulan: df.tanggal.dt.month }).groupby([\"kota\", \"bulan\"]).agg({ omzet: [\"total\", \"sum\"] })\nsl.line_chart(bulanan, { x: \"bulan\", y: \"omzet\", by: \"kota\", format: \"compact\" })"},{"g":"Grafik","n":"area_chart","sig":"area_chart(data, {x, y, stack, ...})","d":"Grafik area. `stack: true` menumpuk seri.","k":"const df = sl.dataset(\"penjualan_bulanan\")\nsl.area_chart(df, { x: \"bulan\", y: \"omzet_juta\" })"},{"g":"Grafik","n":"bar_chart","sig":"bar_chart(data, {x, y, by, stack, horizontal, sort, on_select, width, ...})","d":"Grafik batang. `stack`: true, \"normalize\" (100%), \"center\", atau \"layered\". Dengan `on_select: \"rerun\"`, klik batang mengembalikan pilihan.","k":"const df = sl.dataset(\"penjualan\").groupby(\"kota\").agg({ omzet: [\"total\", \"sum\"] })\nsl.bar_chart(df, { x: \"kota\", y: \"omzet\", horizontal: true, sort: true, labels: true, format: \"compact\" })"},{"g":"Grafik","n":"scatter_chart","sig":"scatter_chart(data, {x, y, size, ...})","d":"Grafik titik sebar.","k":"const df = sl.dataset(\"karyawan\")\nsl.scatter_chart(df, { x: \"pengalaman_tahun\", y: \"gaji_juta\", by: \"pendidikan\", trendline: true })"},{"g":"Widget","n":"button","sig":"button(label, {type, icon, help, on_click, width, disabled})","d":"Mengembalikan `true` hanya pada jalan ulang setelah diklik. `type`: \"primary\", \"secondary\", atau \"tertiary\". `icon`: emoji atau \":material/nama:\".","k":"if (sl.button(\"Hitung\", { type: \"primary\", icon: \":material/calculate:\" })) sl.success(\"Tombol ditekan!\")\nelse sl.caption(\"Tekan tombol di atas.\")"},{"g":"Widget","n":"checkbox","sig":"checkbox(label, nilai)","d":"Kotak centang. Mengembalikan true/false.","k":"const setuju = sl.checkbox(\"Saya setuju dengan syarat\")\nsl.write(setuju ? \"Terima kasih :pray:\" : \"Centang untuk melanjutkan.\")"},{"g":"Widget","n":"toggle","sig":"toggle(label, nilai)","d":"Sakelar nyala/mati.","k":"const detail = sl.toggle(\"Tampilkan detail\", { value: true })\nif (detail) sl.dataframe(sl.dataset(\"iris\").head(3))"},{"g":"Widget","n":"radio","sig":"radio(label, opsi, {index, horizontal, captions})","d":"Pilih satu dari beberapa opsi. `captions` menambah keterangan kecil di bawah tiap opsi.","k":"const kanal = sl.radio(\"Kanal\", [\"Semua\", \"Online\", \"Toko\"], { horizontal: true })\nsl.write(\"Dipilih:\", kanal)"},{"g":"Widget","n":"selectbox","sig":"selectbox(label, opsi, {index, placeholder, accept_new_options})","d":"Daftar pilihan tarik-turun. `accept_new_options: true` membolehkan pengguna mengetik pilihan baru.","k":"const kota = sl.selectbox(\"Kota\", [\"Jayapura\", \"Sorong\", \"Merauke\"])\nsl.write(`Kota terpilih: **${kota}**`)"},{"g":"Widget","n":"multiselect","sig":"multiselect(label, opsi, {default, max_selections, accept_new_options})","d":"Pilih beberapa opsi. `accept_new_options: true` membolehkan opsi baru yang diketik.","k":"const buah = sl.multiselect(\"Buah\", [\"Pisang\", \"Mangga\", \"Pepaya\", \"Nanas\"], { default: [\"Pisang\"] })\nsl.write(`${buah.length} buah dipilih`)"},{"g":"Widget","n":"slider","sig":"slider(label, min, max, nilai, step)","d":"Penggeser angka. Jika `nilai` berupa larik [a, b], hasilnya rentang.","k":"const n = sl.slider(\"Diskon (%)\", 0, 50, 10)\nconst rentang = sl.slider(\"Rentang harga (ribu)\", 0, 500, [50, 200])\nsl.write(`Diskon ${n}%, harga ${rentang[0]}–${rentang[1]} ribu`)"},{"g":"Widget","n":"select_slider","sig":"select_slider(label, opsi, {value})","d":"Penggeser untuk daftar opsi.","k":"const ukuran = sl.select_slider(\"Ukuran\", [\"S\", \"M\", \"L\", \"XL\"], { value: \"M\" })\nsl.write(\"Ukuran:\", ukuran)"},{"g":"Widget","n":"text_input","sig":"text_input(label, nilai, {placeholder, type, live, max_chars})","d":"Kotak teks satu baris. Nilai diterapkan saat Enter atau saat pindah fokus. `live: true` untuk setiap ketikan, `type: \"password\"` untuk sandi.","k":"const nama = sl.text_input(\"Nama\", { placeholder: \"Tulis namamu\" })\nif (nama) sl.write(`Halo, ${nama}! :wave:`)"},{"g":"Widget","n":"text_area","sig":"text_area(label, nilai, {height, placeholder})","d":"Kotak teks banyak baris. Ctrl+Enter untuk menerapkan.","k":"const catatan = sl.text_area(\"Catatan\", { value: \"Barang dikirim besok.\", height: 100 })\nsl.caption(`${catatan.length} karakter`)"},{"g":"Widget","n":"number_input","sig":"number_input(label, {min, max, value, step})","d":"Input angka dengan tombol + dan −.","k":"const jumlah = sl.number_input(\"Jumlah\", { min_value: 1, max_value: 100, value: 3 })\nsl.write(`Total: Rp ${(jumlah * 15000).toLocaleString(\"id-ID\")}`)"},{"g":"Widget","n":"date_input","sig":"date_input(label, \"YYYY-MM-DD\")","d":"Pemilih tanggal. Mengembalikan string \"YYYY-MM-DD\".","k":"const tgl = sl.date_input(\"Tanggal kirim\", { value: \"2024-08-17\" })\nsl.write(\"Dikirim pada\", tgl)"},{"g":"Widget","n":"time_input","sig":"time_input(label, \"HH:MM\")","d":"Pemilih jam.","k":"const jam = sl.time_input(\"Jam buka\", { value: \"08:00\" })\nsl.write(\"Buka pukul\", jam)"},{"g":"Widget","n":"color_picker","sig":"color_picker(label, \"#rrggbb\")","d":"Pemilih warna.","k":"const warna = sl.color_picker(\"Warna tema\", \"#0f766e\")\nsl.markdown(`<span style=\"color:${warna}\">■■■</span> ${warna}`, { unsafe_allow_html: true })"},{"g":"Widget","n":"file_uploader","sig":"file_uploader(label, {type, accept_multiple_files})","d":"Unggah berkas. Hasilnya punya `.name`, `.size`, `.text`, `.bytes`, `.url`, `.json()`, `.csv()`.","k":"const f = sl.file_uploader(\"Unggah CSV\", { type: \"csv\" })\nif (f) sl.dataframe(await sl.read_csv(f))\nelse sl.caption(\"Pilih berkas CSV untuk melihat isinya.\")"},{"g":"Widget","n":"download_button","sig":"download_button(label, data, {file_name, mime})","d":"Tombol untuk mengunduh teks, objek, atau CSV.","k":"const df = sl.dataset(\"iris\").head(20)\nsl.download_button(\"Unduh CSV\", df, { file_name: \"iris.csv\", icon: \":material/download:\" })\nsl.download_button(\"Unduh Excel\", df, { file_name: \"iris.xlsx\" })"},{"g":"Widget","n":"link_button","sig":"link_button(label, url)","d":"Tombol yang membuka tautan.","k":"sl.link_button(\"Buka dokumentasi\", \"https://example.com\", { icon: \":material/open_in_new:\" })"},{"g":"Tata letak","n":"sidebar","sig":"sidebar.<fungsi>(…)","d":"Semua fungsi bisa dipanggil lewat `sl.sidebar` agar tampil di panel samping.","k":"const kota = sl.sidebar.selectbox(\"Kota\", [\"Jayapura\", \"Sorong\"])\nsl.sidebar.caption(\"Filter ada di sidebar\")\nsl.write(\"Menampilkan data\", kota)"},{"g":"Tata letak","n":"columns","sig":"columns(n | [bobot], {gap})","d":"Membagi baris menjadi kolom. Mengembalikan larik; tiap kolom punya semua fungsi.","k":"const [kiri, kanan] = sl.columns([2, 1])\nkiri.bar_chart([{ k: \"A\", n: 3 }, { k: \"B\", n: 5 }], { x: \"k\", y: \"n\" })\nkanan.metric(\"Total\", 8)"},{"g":"Tata letak","n":"tabs","sig":"tabs([label])","d":"Membuat tab. Mengembalikan larik wadah.","k":"const [grafik, tabel] = sl.tabs([\":bar_chart: Grafik\", \":material/table: Tabel\"])\nconst df = sl.dataset(\"penjualan\").groupby(\"kota\").agg({ omzet: [\"total\", \"sum\"] })\ngrafik.bar_chart(df, { x: \"kota\", y: \"omzet\" })\ntabel.dataframe(df)"},{"g":"Tata letak","n":"expander","sig":"expander(label, {expanded}, fn?)","d":"Bagian yang bisa dibuka-tutup.","k":"sl.expander(\"Lihat rumus\", (e) => {\n  e.latex(\"\\\\text{margin} = \\\\frac{\\\\text{laba}}{\\\\text{omzet}}\")\n}, { expanded: true })"},{"g":"Tata letak","n":"container","sig":"container({border, height, horizontal, gap, horizontal_alignment, vertical_alignment, width, autoscroll}, fn)","d":"Wadah elemen. `horizontal: true` menyusun isi berjajar (flex). `height` angka membuat wadah bergulir.","k":"const kotak = sl.container({ border: true })\nkotak.subheader(\"Ringkasan\")\nkotak.write(\"Isi di dalam wadah berbingkai.\")"},{"g":"Tata letak","n":"empty","sig":"empty()","d":"Placeholder satu elemen yang isinya diganti setiap kali ditulisi.","k":"const tempat = sl.empty()\nfor (let i = 3; i > 0; i--) { tempat.metric(\"Hitung mundur\", i); await sl.sleep(400) }\ntempat.success(\"Mulai!\")"},{"g":"Tata letak","n":"form","sig":"form(key, {clear_on_submit}, fn?)","d":"Widget di dalam form baru diterapkan saat tombol kirim ditekan.","k":"const f = sl.form(\"tamu\")\nconst nama = f.text_input(\"Nama\")\nconst kota = f.selectbox(\"Kota\", [\"Jayapura\", \"Sorong\"])\nif (f.form_submit_button(\"Kirim\")) sl.success(`Terima kasih, ${nama || \"tamu\"} dari ${kota}!`)"},{"g":"Tata letak","n":"form_submit_button","sig":"form_submit_button(label, {type})","d":"Tombol kirim di dalam form. Mengembalikan true saat dikirim.","k":"const f = sl.form(\"cari\", { border: true })\nconst q = f.text_input(\"Kata kunci\")\nif (f.form_submit_button(\"Cari\", { type: \"primary\", icon: \":mag:\" })) sl.write(\"Mencari:\", q)"},{"g":"Chat & media","n":"chat_message","sig":"chat_message(peran, {avatar})","d":"Gelembung pesan. Peran: \"user\" atau \"assistant\".","k":"sl.chat_message(\"user\").write(\"Berapa omzet bulan ini?\")\nsl.chat_message(\"assistant\").write(\"Omzet bulan ini **Rp 12,5 juta**, naik 8%.\")"},{"g":"Chat & media","n":"chat_input","sig":"chat_input(placeholder, {accept_file, file_type, accept_audio, max_chars, key})","d":"Kotak pesan chat. Di halaman utama menempel di bawah; di dalam wadah tampil di tempat. Dengan `accept_file`/`accept_audio`, hasilnya `{text, files, audio}`.","k":"const pesan = sl.chat_input(\"Tulis pesan…\")\nif (pesan) {\n  sl.chat_message(\"user\").write(pesan)\n  sl.chat_message(\"assistant\").write(\"Kamu menulis: \" + pesan)\n}"},{"g":"Chat & media","n":"image","sig":"image(src, {caption, width})","d":"Gambar dari URL atau berkas unggahan.","k":"const gambar = \"data:image/svg+xml;utf8,\" + encodeURIComponent('<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"600\" height=\"220\"><rect width=\"600\" height=\"220\" fill=\"#0f766e\"/><text x=\"300\" y=\"125\" font-size=\"42\" text-anchor=\"middle\" fill=\"white\" font-family=\"sans-serif\">Gambar contoh</text></svg>')\nsl.image(gambar, { caption: \"Gambar dari teks SVG\", width: 400 })"},{"g":"Chat & media","n":"audio","sig":"audio(src)","d":"Pemutar audio.","k":"sl.audio(\"https://upload.wikimedia.org/wikipedia/commons/c/c8/Example.ogg\")","online":1},{"g":"Chat & media","n":"video","sig":"video(src, {subtitles, start_time, end_time, loop, autoplay, muted})","d":"Pemutar video. `subtitles` berupa teks/URL SRT atau VTT, atau objek `{ \"Indonesia\": ... }`.","k":"sl.video(\"https://upload.wikimedia.org/wikipedia/commons/transcoded/c/c0/Big_Buck_Bunny_4K.webm/Big_Buck_Bunny_4K.webm.160p.webm\")","online":1},{"g":"Halaman","n":"navigation","sig":"navigation([halaman] | {Bagian: [halaman]}, {position})","d":"Membuat aplikasi multi-halaman dengan menu. Mengembalikan halaman aktif; panggil `.run()`. `position`: \"sidebar\", \"top\", atau \"hidden\".","k":"function beranda(sl) {\n  sl.title(\"Beranda :house:\")\n  sl.page_link(\"Data\", { icon: \":bar_chart:\" })\n}\nfunction data(sl) {\n  sl.title(\"Data :bar_chart:\")\n  sl.dataframe(sl.dataset(\"iris\").head())\n}\nconst halaman = sl.navigation([\n  sl.page(\"Beranda\", beranda, { icon: \":house:\" }),\n  sl.page(\"Data\", data, { icon: \":bar_chart:\" })\n])\nhalaman.run()"},{"g":"Halaman","n":"page","sig":"page(judul, fungsi, {icon, url, default, roles})","d":"Mendefinisikan satu halaman. Fungsinya menerima `sl`. `roles: [\"admin\"]` menyembunyikan halaman dari pengguna tanpa peran itu (lihat sl.login).","k":"function beranda(sl) {\n  sl.title(\"Beranda :house:\")\n  sl.page_link(\"Data\", { icon: \":bar_chart:\" })\n}\nfunction data(sl) {\n  sl.title(\"Data :bar_chart:\")\n  sl.dataframe(sl.dataset(\"iris\").head())\n}\nconst halaman = sl.navigation([\n  sl.page(\"Beranda\", beranda, { icon: \":house:\" }),\n  sl.page(\"Data\", data, { icon: \":bar_chart:\" })\n])\nhalaman.run()"},{"g":"Halaman","n":"switch_page","sig":"switch_page(judul | halaman)","d":"Pindah ke halaman lain sekarang juga.","k":"function beranda(sl) {\n  sl.title(\"Beranda\")\n  if (sl.button(\"Ke halaman Data\")) sl.switch_page(\"Data\")\n}\nfunction data(sl) { sl.title(\"Data\"); sl.write(\"Kamu di halaman Data.\") }\nsl.navigation([sl.page(\"Beranda\", beranda), sl.page(\"Data\", data)]).run()"},{"g":"Halaman","n":"page_link","sig":"page_link(judul | url, {label, icon})","d":"Tautan ke halaman lain di aplikasi, atau ke situs luar.","k":"function beranda(sl) {\n  sl.title(\"Beranda :house:\")\n  sl.page_link(\"Data\", { icon: \":bar_chart:\" })\n}\nfunction data(sl) {\n  sl.title(\"Data :bar_chart:\")\n  sl.dataframe(sl.dataset(\"iris\").head())\n}\nconst halaman = sl.navigation([\n  sl.page(\"Beranda\", beranda, { icon: \":house:\" }),\n  sl.page(\"Data\", data, { icon: \":bar_chart:\" })\n])\nhalaman.run()"},{"g":"Penyimpanan","n":"local_state","sig":"local_state","d":"Seperti `session_state`, tetapi tetap tersimpan walau halaman ditutup. Hanya untuk data JSON. Widget bisa diingat dengan opsi `persist: true`.","k":"sl.local_state.kunjungan = (sl.local_state.kunjungan || 0) + 1\nsl.write(`Kamu sudah membuka aplikasi ini **${sl.local_state.kunjungan}** kali.`)\nsl.caption(\"Nilainya tetap ada walau halaman ditutup.\")"},{"g":"Penyimpanan","n":"clear_local_state","sig":"clear_local_state()","d":"Mengosongkan semua isi `local_state` aplikasi ini.","k":"sl.local_state.n = (sl.local_state.n || 0) + 1\nsl.write(\"Hitungan tersimpan:\", sl.local_state.n)\nif (sl.button(\"Hapus data tersimpan\")) { sl.clear_local_state(); sl.rerun() }"},{"g":"Penyimpanan","n":"db","sig":"db(nama, {tabel: \"++id, indeks\"})","d":"Database IndexedDB yang tersimpan permanen. Tabel diakses lewat `db.tabel` dengan insert, get, update, delete, where, all. Semua perintahnya memakai `await`.","k":"const db = sl.db(\"contoh_toko\", { produk: \"++id, nama, stok\" })\nif ((await db.produk.count()) === 0) { await db.produk.insert({ nama: \"Kopi\", stok: 12 }); await db.produk.insert({ nama: \"Teh\", stok: 4 }) }\nsl.dataframe(await db.produk.all(), { hide_index: true })"},{"g":"Penyimpanan","n":"data_editor","sig":"data_editor(data | db.tabel, {num_rows, column_config, disabled})","d":"Tabel yang bisa diketik langsung. Larik masuk → larik keluar; DataFrame masuk → DataFrame keluar. Daftar perubahan ada di `hasil.edits` (edited_rows, added_rows, deleted_rows). Dengan tabel sl.db: perubahan langsung tersimpan (pakai `await`). Untuk SQLite: `db.save_edits(tabel, data, hasil)`.","k":"const awal = [{ barang: \"Kopi\", stok: 12, aktif: true }, { barang: \"Teh\", stok: 4, aktif: false }]\nconst hasil = sl.data_editor(awal, { num_rows: \"dynamic\", key: \"stok\" })\nsl.write(\"Total stok:\", hasil.reduce((a, r) => a + (r.stok || 0), 0))"},{"g":"Penyimpanan","n":"db_list","sig":"await db_list()","d":"Daftar nama database di browser ini.","k":"sl.db(\"contoh_toko\", { produk: \"++id, nama\" })\nsl.write(await sl.db_list())"},{"g":"Kontrol","n":"session_state","sig":"session_state","d":"Objek yang nilainya bertahan antar-jalan ulang. Widget dengan `key` otomatis tersimpan di sini.","k":"if (sl.session_state.hitung == null) sl.session_state.hitung = 0\nif (sl.button(\"Tambah\")) sl.session_state.hitung++\nsl.metric(\"Hitungan\", sl.session_state.hitung)"},{"g":"Kontrol","n":"sleep","sig":"await sleep(ms)","d":"Menunggu beberapa milidetik. Pakai `await`.","k":"sl.write(\"Menunggu…\")\nawait sl.sleep(500)\nsl.write(\"Selesai menunggu setengah detik.\")"},{"g":"Kontrol","n":"rerun","sig":"rerun({scope})","d":"Menjalankan ulang skrip. Di dalam fragment, `sl.rerun({ scope: \"fragment\" })` hanya menjalankan fragment itu.","k":"sl.session_state.n = (sl.session_state.n || 0)\nif (sl.button(\"Naikkan lalu jalankan ulang\")) { sl.session_state.n++; sl.rerun() }\nsl.write(\"n =\", sl.session_state.n)"},{"g":"Kontrol","n":"stop","sig":"stop()","d":"Menghentikan skrip di titik ini.","k":"const nama = sl.text_input(\"Nama\")\nif (!nama) { sl.info(\"Isi nama dulu.\"); sl.stop() }\nsl.success(`Halo, ${nama}!`)"},{"g":"Kontrol","n":"cache_data","sig":"cache_data(fungsi, {ttl, max_entries})","d":"Menyimpan hasil fungsi. `ttl` dalam detik atau \"10m\". `fungsi.clear()` mengosongkan cache fungsi itu; `sl.cache_data.clear()` mengosongkan semuanya.","k":"const hitungLama = sl.cache_data(async (n) => { await sl.sleep(800); return n * n })\nconst n = sl.slider(\"n\", 1, 10, 4)\nsl.write(\"Hasil:\", await hitungLama(n), \"(nilai yang sama langsung diambil dari simpanan)\")"},{"g":"Kontrol","n":"set_page_config","sig":"set_page_config({page_title, page_icon, layout})","d":"Mengatur judul tab, ikon, dan `layout: \"wide\"`.","k":"sl.set_page_config({ page_title: \"Dasbor Toko\", page_icon: \":convenience_store:\", layout: \"wide\" })\nsl.title(\"Lihat judul tab dan ikonnya\")"},{"g":"Kontrol","n":"parse_csv","sig":"parse_csv(teks)","d":"Mengubah teks CSV menjadi larik objek. Angka otomatis dikonversi.","k":"const baris = sl.parse_csv(\"kota,omzet\\nJayapura,12\\nSorong,8\")\nsl.write(baris)"},{"g":"Kontrol","n":"to_csv","sig":"to_csv(data)","d":"Mengubah data menjadi teks CSV.","k":"sl.code(sl.to_csv([{ kota: \"Jayapura\", omzet: 12 }, { kota: \"Sorong\", omzet: 8 }]))"},{"g":"Kontrol","n":"query_params","sig":"query_params.get(k) / .set(k, v)","d":"Membaca dan menulis parameter URL.","k":"sl.query_params.kota = sl.selectbox(\"Kota\", [\"Jayapura\", \"Sorong\"])\nsl.write(\"Alamat halaman kini berisi ?kota=\", sl.query_params.kota)"},{"g":"Grafik 1.2","n":"histogram","sig":"histogram(data, {x, bins, by, density, percent})","d":"Sebaran nilai angka. Garis putus-putus menandai rata-rata. `by` membandingkan beberapa kelompok.","k":"const df = sl.dataset(\"karyawan\")\nsl.histogram(df, { x: \"gaji_juta\", bins: 20, title: \"Sebaran gaji (juta)\" })"},{"g":"Grafik 1.2","n":"box_plot","sig":"box_plot(data, {y, by, show_mean})","d":"Kotak median, kuartil, dan pencilan. Cocok untuk membandingkan kelompok.","k":"const df = sl.dataset(\"karyawan\")\nsl.box_plot(df, { y: \"gaji_juta\", by: \"pendidikan\" })"},{"g":"Grafik 1.2","n":"pie_chart","sig":"pie_chart(data, {names, values, donut, max_slices})","d":"Diagram lingkaran/donut. Irisan kecil digabung menjadi \"Lainnya\".","k":"const df = sl.dataset(\"penjualan\")\nsl.pie_chart(df, { names: \"kategori\", values: \"total\", donut: true })"},{"g":"Grafik 1.2","n":"heatmap","sig":"heatmap(data, {x, y, value, annot, scale, format})","d":"Peta warna, misalnya matriks korelasi `df.corr()` atau tabel pivot.","k":"const df = sl.dataset(\"karyawan\").select([\"pengalaman_tahun\", \"jam_pelatihan\", \"nilai_kinerja\", \"gaji_juta\"])\nsl.heatmap(df.corr(), { labels: true })"},{"g":"Grafik 1.2","n":"combo_chart","sig":"combo_chart(data, {x, bar, line, y2})","d":"Batang dan garis dalam satu grafik; garis memakai sumbu kanan.","k":"const df = sl.dataset(\"penjualan_bulanan\").tail(12).assign({ tumbuh: r => r.omzet_juta * 0.1 })\nsl.combo_chart(df, { x: \"bulan\", bar: \"omzet_juta\", line: \"tumbuh\" })"},{"g":"Grafik 1.2","n":"bar_chart","sig":"bar_chart(data, {x, y, by, horizontal, sort, labels, stack, color, format})","d":"Opsi baru 1.2: `horizontal`, `sort`, `labels`, `by` (data panjang), `format: \"rupiah\"`, dan `color` berupa fungsi `(baris) => warna`.","k":"const df = sl.dataset(\"penjualan\").groupby(\"kota\").agg({ omzet: [\"total\", \"sum\"] })\nsl.bar_chart(df, { x: \"kota\", y: \"omzet\", horizontal: true, sort: true, labels: true, format: \"compact\" })"},{"g":"Grafik 1.2","n":"scatter_chart","sig":"scatter_chart(data, {x, y, by, trendline, size, zero})","d":"`trendline: true` menambah garis tren dan R². `by` memberi warna per kelompok. Sumbu mengikuti rentang data (`zero: true` untuk mulai dari 0). Lebih dari 3.000 titik digambar sebagai satu gambar, ratusan ribu titik tetap ringan.","k":"const df = sl.dataset(\"karyawan\")\nsl.scatter_chart(df, { x: \"pengalaman_tahun\", y: \"gaji_juta\", by: \"pendidikan\", trendline: true })"},{"g":"Grafik 1.2","n":"line_chart","sig":"line_chart(data, {x, y, by, labels, format, y_min, y_max, zero})","d":"Sumbu tanggal otomatis bila x berupa tanggal. `by` membuat satu garis per kelompok. `zero: false` membuat sumbu mengikuti rentang data, tidak mulai dari 0.","k":"const df = sl.dataset(\"penjualan\")\nconst bulanan = df.assign({ bulan: df.tanggal.dt.month }).groupby([\"kota\", \"bulan\"]).agg({ omzet: [\"total\", \"sum\"] })\nsl.line_chart(bulanan, { x: \"bulan\", y: \"omzet\", by: \"kota\", format: \"compact\" })"},{"g":"Slak Data","n":"dataset","sig":"dataset(nama)","d":"Dataset contoh siap pakai: penjualan, penjualan_bulanan, kunjungan_harian, pelanggan, ab_test, karyawan, nilai_ujian, data_kotor, iris.","k":"const df = sl.dataset(\"penjualan\")\nsl.write(`${df.length} baris × ${df.columns.length} kolom`)\nsl.dataframe(df.head())"},{"g":"Slak Data","n":"datasets","sig":"datasets()","d":"Daftar dataset contoh beserta keterangannya.","k":"sl.dataframe(sl.datasets(), { hide_index: true })"},{"g":"Slak Data","n":"DataFrame","sig":"DataFrame(data)","d":"Membuat tabel data dari larik objek atau objek kolom. Kolom dibaca dengan `df.nama` atau `df[\"nama kolom\"]`.","k":"const df = sl.DataFrame([{ nama: \"Ani\", nilai: 90 }, { nama: \"Budi\", nilai: 75 }, { nama: \"Citra\", nilai: 82 }])\nsl.dataframe(df)\nsl.write(\"Rata-rata:\", df.nilai.mean())"},{"g":"Slak Data","n":"read_csv","sig":"await read_csv(sumber, {sep, decimal, dtype, parse_dates})","d":"Membaca CSV dari nama berkas, URL, atau hasil `file_uploader`. Format Indonesia (`;` dan `1.250,50`) dikenali. Saat halaman dibuka dengan klik dua kali, Slak mencari `nama.csv.js` (hasil Alat → Bungkus data), data di dalam halaman, lalu menawarkan tombol pilih berkas.","k":"// Berkas di folder yang sama: await sl.read_csv(\"penjualan.csv\")\nconst df = await sl.read_csv(\"kota,omzet\\nJayapura,12\\nSorong,8\\nMerauke,5\")\nsl.bar_chart(df, { x: \"kota\", y: \"omzet\" })"},{"g":"Slak Data","n":"read_excel","sig":"await read_excel(sumber, {sheet, header, skiprows})","d":"Membaca berkas Excel .xlsx tanpa pustaka tambahan.","k":"const f = sl.file_uploader(\"Pilih berkas Excel\", { type: [\"xlsx\"] })\nif (f) sl.dataframe(await sl.read_excel(f))\nelse sl.caption(\"Unggah .xlsx untuk membacanya.\")"},{"g":"Slak Data","n":"read_json","sig":"await read_json(sumber)","d":"Membaca JSON; objek bersarang diratakan menjadi kolom.","k":"const df = await sl.read_json('[{\"kota\":\"Jayapura\",\"n\":3},{\"kota\":\"Sorong\",\"n\":5}]')\nsl.dataframe(df)"},{"g":"Slak Data","n":"read_sheets","sig":"await read_sheets(url, {sheet})","d":"Membaca Google Sheets yang dibagikan \"Siapa saja yang memiliki link\". Butuh internet. Sejak 1.6 juga jalan di halaman yang dibuka dengan klik dua kali (lewat JSONP ke docs.google.com); untuk itu pakai link bagikan biasa (…/d/ID/edit), bukan link \"Publikasikan ke web\".","k":"// Google Sheets yang dibagikan \"siapa saja yang memiliki link\"\nconst df = await sl.read_sheets(\"https://docs.google.com/spreadsheets/d/1BxiMVs0XRA5nFMdKvBdBZjgmUUqptlbs74OgvE2upms/edit\")\nsl.dataframe(df.head())","online":1},{"g":"Slak Data","n":"excel_sheets","sig":"await excel_sheets(sumber)","d":"Daftar nama sheet di berkas Excel.","k":"const f = sl.file_uploader(\"Pilih berkas Excel\", { type: [\"xlsx\"] })\nif (f) sl.write(\"Lembar kerja:\", await sl.excel_sheets(f))"},{"g":"Slak Data","n":"from_csv","sig":"from_csv(teks, opsi)","d":"Seperti read_csv, tetapi dari teks CSV langsung (tanpa await).","k":"sl.dataframe(sl.from_csv(\"a;b\\n1,5;2\\n3,25;4\"))"},{"g":"Slak Data","n":"to_excel","sig":"to_excel({ Sheet1: df, Sheet2: df2 })","d":"Membuat berkas Excel (Blob) berisi satu atau beberapa sheet. Pakai dengan download_button.","k":"const df = sl.dataset(\"iris\")\nsl.download_button(\"Unduh Excel 2 lembar\", sl.to_excel({ Data: df, Ringkasan: df.describe() }), { file_name: \"iris.xlsx\" })"},{"g":"Slak Data","n":"concat","sig":"concat([df1, df2], {axis})","d":"Menyambung beberapa tabel ke bawah (axis 0) atau ke samping (axis 1).","k":"const a = sl.DataFrame([{ kota: \"Jayapura\", n: 3 }])\nconst b = sl.DataFrame([{ kota: \"Sorong\", n: 5 }])\nsl.dataframe(sl.concat([a, b]))"},{"g":"Slak Data","n":"merge","sig":"merge(kiri, kanan, {on, how})","d":"Menggabungkan dua tabel berdasarkan kolom kunci, seperti JOIN atau VLOOKUP. `how`: inner, left, right, outer.","k":"const jual = sl.DataFrame([{ produk: \"Kopi\", qty: 3 }, { produk: \"Teh\", qty: 5 }])\nconst harga = sl.DataFrame([{ produk: \"Kopi\", harga: 15000 }, { produk: \"Teh\", harga: 8000 }])\nsl.dataframe(sl.merge(jual, harga, { on: \"produk\", how: \"left\" }))"},{"g":"Slak Data","n":"cut","sig":"cut(series, batas | jumlah, {labels})","d":"Mengelompokkan angka ke rentang, misalnya umur ke kelompok umur.","k":"const df = sl.dataset(\"pelanggan\")\nconst kelompok = sl.cut(df.umur, [0, 25, 40, 60, 100], { labels: [\"muda\", \"dewasa\", \"paruh baya\", \"lansia\"] })\nsl.bar_chart(kelompok.value_counts())"},{"g":"Slak Data","n":"qcut","sig":"qcut(series, jumlah, {labels})","d":"Mengelompokkan berdasarkan kuantil sehingga setiap kelompok berisi jumlah data yang sama.","k":"const df = sl.dataset(\"penjualan\")\nsl.write(sl.qcut(df.total, 4).value_counts())"},{"g":"Slak Data","n":"get_dummies","sig":"get_dummies(df, kolom, {drop_first})","d":"One-hot encoding: kolom kategori menjadi kolom 0/1.","k":"sl.dataframe(sl.get_dummies(sl.dataset(\"penjualan\").select([\"kota\", \"total\"]).head(5), [\"kota\"]))"},{"g":"Slak Data","n":"crosstab","sig":"crosstab(a, b, {normalize, margins})","d":"Tabel silang frekuensi dua kolom kategori.","k":"const df = sl.dataset(\"penjualan\")\nsl.dataframe(sl.crosstab(df.kota, df.kanal))"},{"g":"Slak Data","n":"date_range","sig":"date_range(mulai, {periods, end, freq})","d":"Deret tanggal. `freq`: \"D\", \"W\", \"M\", \"Q\", \"Y\" (melangkah dari tanggal awal; 31 Jan + 1 bulan = 29 Feb), \"ME\"/\"QE\"/\"YE\" untuk akhir periode, \"MS\"/\"QS\"/\"YS\" untuk awal periode.","k":"sl.write(sl.date_range(\"2024-01-01\", { periods: 6, freq: \"M\" }))"},{"g":"Slak Data","n":"to_datetime","sig":"to_datetime(nilai, {format, dayfirst})","d":"Mengubah teks menjadi tanggal. Format Indonesia 31/12/2024 dan \"5 Januari 2024\" dikenali.","k":"const s = sl.to_datetime(sl.DataFrame({ t: [\"17/08/2024\", \"01/09/2024\"] }).t, { dayfirst: true })\nsl.write(s)"},{"g":"Slak Data","n":"to_numeric","sig":"to_numeric(nilai, {decimal})","d":"Mengubah teks seperti \"Rp 1.250.000\" menjadi angka.","k":"const s = sl.to_numeric(sl.DataFrame({ harga: [\"Rp 15.000\", \"8.500\", \"-\"] }).harga)\nsl.write(s)"},{"g":"Slak Data","n":"stats","sig":"stats.<fungsi>(…)","d":"Statistik: uji-t, ANOVA, chi-kuadrat, korelasi, regresi, uji A/B. Ketik `sl.stats.` untuk melihat daftarnya.","k":"sl.write(sl.stats.ttest_ind(sl.dataset(\"ab_test\"), { value: \"nilai_belanja\", group: \"grup\" }))"},{"g":"Slak Data","n":"ml","sig":"ml.<fungsi>(…)","d":"Machine learning gaya scikit-learn: model, metrik, validasi silang. Ketik `sl.ml.`.","k":"const df = sl.dataset(\"iris\")\nconst model = new sl.ml.RandomForestClassifier().fit(df.drop(\"spesies\"), df.spesies)\nsl.write(\"Akurasi latih:\", model.score(df.drop(\"spesies\"), df.spesies))"},{"g":"Slak Data","n":"ts","sig":"ts.<fungsi>(…)","d":"Deret waktu: dekomposisi, peramalan, autokorelasi. Ketik `sl.ts.`.","k":"sl.write(sl.ts.forecast(sl.dataset(\"penjualan_bulanan\"), { periods: 6 }))"},{"g":"Slak Data","n":"analysis","sig":"analysis.<fungsi>(…)","d":"Analisis bisnis siap pakai: kohort, RFM, funnel, Pareto, pertumbuhan. Ketik `sl.analysis.`.","k":"sl.write(sl.analysis.pareto(sl.dataset(\"penjualan\"), { category: \"produk\", value: \"total\" }))"},{"g":"SQL & Python","n":"sql","sig":"await sql(kueri, { nama_tabel: df }, {params, portable, all_columns})","d":"SQL sungguhan (SQLite) atas DataFrame. Sintaks PostgreSQL yang umum ikut dikenali: `date_trunc`, `EXTRACT`, `::date`, `ILIKE`, `percentile_cont(...) WITHIN GROUP`, `INTERVAL`. `portable: true` memperingatkan sintaks yang hanya ada di SQLite. Hanya kolom yang disebut kueri yang dimuat ke SQLite (jauh lebih cepat untuk tabel lebar); `all_columns: true` memuat semua.","k":"const df = sl.dataset(\"penjualan\")\nconst r = await sl.sql(\"SELECT kota, SUM(total) AS omzet FROM jual GROUP BY kota ORDER BY omzet DESC\", { jual: df })\nsl.dataframe(r)"},{"g":"SQL & Python","n":"sqlite","sig":"await sqlite(berkas | {name})","d":"Membuka berkas .db/.sqlite, atau membuat database SQLite yang tersimpan di browser (`{ name }`). Perintah: query, insert, tables, schema, export, save_edits (menyimpan hasil data_editor ke tabel).","k":"const db = await sl.sqlite({ name: \"contoh_kas\" })\ndb.run(\"CREATE TABLE IF NOT EXISTS kas (id INTEGER PRIMARY KEY, ket TEXT, nilai REAL)\")\nif (!db.query(\"SELECT COUNT(*) n FROM kas\").n.values[0]) db.run(\"INSERT INTO kas (ket, nilai) VALUES ('Modal', 500000), ('Beli stok', -200000)\")\nsl.dataframe(db.query(\"SELECT * FROM kas\"))\nsl.metric(\"Saldo\", db.query(\"SELECT SUM(nilai) s FROM kas\").s.values[0])"},{"g":"SQL & Python","n":"python","sig":"await python(kode, { df: tabel })","d":"Menjalankan Python asli (Pyodide) beserta pandas, numpy, scikit-learn, atau matplotlib. Tabel dikirim dengan nama variabelnya, misalnya `{ df: penjualan }`. Butuh internet saat pertama kali dimuat.","k":"const df = sl.dataset(\"penjualan\")\nconst r = await sl.python(`\nringkas = df.groupby(\"kota\").total.agg([\"count\", \"sum\"]).sort_values(\"sum\", ascending=False)\nprint(\"Kota dengan omzet terbesar:\", ringkas.index[0])\nringkas`, { df })\nsl.write(r)   // menampilkan keluaran print() dan tabel hasilnya","online":1},{"g":"DataFrame","n":"head","sig":"head(n)","d":"n baris pertama (bawaan 5).","ns":"df","k":"const df = sl.dataset(\"penjualan\")\nsl.dataframe(df.head(3))"},{"g":"DataFrame","n":"tail","sig":"tail(n)","d":"n baris terakhir.","ns":"df","k":"const df = sl.dataset(\"penjualan\")\nsl.dataframe(df.tail(3))"},{"g":"DataFrame","n":"sample","sig":"sample(n, {seed})","d":"Ambil baris acak.","ns":"df","k":"const df = sl.dataset(\"penjualan\")\nsl.dataframe(df.sample(3, { random_state: 1 }))"},{"g":"DataFrame","n":"info","sig":"info()","d":"Ringkasan kolom: tipe, terisi, kosong, unik.","ns":"df","k":"sl.info(\"Data diperbarui setiap Senin pagi.\", { icon: \":information_source:\" })"},{"g":"DataFrame","n":"describe","sig":"describe({include})","d":"Statistik deskriptif kolom angka.","ns":"df","k":"const df = sl.dataset(\"penjualan\")\nsl.dataframe(df.describe())"},{"g":"DataFrame","n":"shape","sig":"shape","d":"[jumlah baris, jumlah kolom].","ns":"df","k":"const df = sl.dataset(\"penjualan\")\nsl.write(\"Baris × kolom:\", df.shape)"},{"g":"DataFrame","n":"columns","sig":"columns","d":"Daftar nama kolom.","ns":"df","k":"const [kiri, kanan] = sl.columns([2, 1])\nkiri.bar_chart([{ k: \"A\", n: 3 }, { k: \"B\", n: 5 }], { x: \"k\", y: \"n\" })\nkanan.metric(\"Total\", 8)"},{"g":"DataFrame","n":"dtypes","sig":"dtypes","d":"Tipe data tiap kolom.","ns":"df","k":"const df = sl.dataset(\"penjualan\")\nsl.write(df.dtypes)"},{"g":"DataFrame","n":"missing","sig":"missing()","d":"Jumlah dan persen nilai kosong per kolom.","ns":"df","k":"const df = sl.dataset(\"data_kotor\")\nsl.dataframe(df.missing())"},{"g":"DataFrame","n":"value_counts","sig":"value_counts(kolom, {normalize})","d":"Frekuensi tiap nilai.","ns":"df","k":"const df = sl.dataset(\"penjualan\")\nsl.dataframe(df.value_counts(\"kota\"))"},{"g":"DataFrame","n":"unique","sig":"unique(kolom)","d":"Nilai unik sebuah kolom.","ns":"df","k":"const df = sl.dataset(\"penjualan\")\nsl.write(df.unique(\"kanal\"))"},{"g":"DataFrame","n":"nunique","sig":"nunique()","d":"Banyak nilai unik per kolom.","ns":"df","k":"const df = sl.dataset(\"penjualan\")\nsl.write(df.nunique())"},{"g":"DataFrame","n":"select","sig":"select([kolom])","d":"Ambil beberapa kolom.","ns":"df","k":"const df = sl.dataset(\"penjualan\")\nsl.dataframe(df.select([\"kota\", \"total\"]).head(3))"},{"g":"DataFrame","n":"drop","sig":"drop(kolom)","d":"Buang kolom.","ns":"df","k":"const df = sl.dataset(\"penjualan\")\nsl.dataframe(df.drop([\"id_transaksi\", \"pelanggan_id\"]).head(3))"},{"g":"DataFrame","n":"rename","sig":"rename({lama: \"baru\"})","d":"Ganti nama kolom.","ns":"df","k":"const df = sl.dataset(\"penjualan\")\nsl.dataframe(df.rename({ total: \"omzet\" }).select([\"kota\", \"omzet\"]).head(3))"},{"g":"DataFrame","n":"clean_names","sig":"clean_names()","d":"Rapikan nama kolom menjadi huruf kecil_dengan_garis_bawah.","ns":"df","k":"const df = sl.DataFrame([{ \"Nama Barang\": \"Kopi\", \"Harga (Rp)\": 15000 }])\nsl.write(df.clean_names().columns)"},{"g":"DataFrame","n":"assign","sig":"assign({kolom: (baris) => nilai})","d":"Tambah atau ubah kolom.","ns":"df","k":"const df = sl.dataset(\"penjualan\")\nsl.dataframe(df.assign({ pajak: r => r.total * 0.11 }).select([\"total\", \"pajak\"]).head(3))"},{"g":"DataFrame","n":"astype","sig":"astype({kolom: \"number\"})","d":"Ubah tipe kolom: number, int, string, date, boolean.","ns":"df","k":"const df = sl.DataFrame({ umur: [\"21\", \"35\"], aktif: [1, 0] })\nsl.write(df.astype({ umur: \"int\", aktif: \"bool\" }).dtypes)"},{"g":"DataFrame","n":"query","sig":"query(\"ekspresi\", {var})","d":"Saring baris dengan ekspresi teks, misalnya `\"total > 100000 and kota == 'Sorong'\"`.","ns":"df","k":"const df = sl.dataset(\"penjualan\")\nsl.dataframe(df.query(\"total > 1000000 and kanal == 'Online'\").head(5))"},{"g":"DataFrame","n":"filter","sig":"filter((baris) => kondisi)","d":"Saring baris dengan fungsi, Series benar/salah, atau objek `{kolom: nilai}`.","ns":"df","k":"const df = sl.dataset(\"penjualan\")\nsl.dataframe(df.filter(df.kota.isin([\"Sorong\", \"Biak\"])).head(5))"},{"g":"DataFrame","n":"sort_values","sig":"sort_values(kolom, {ascending})","d":"Urutkan baris.","ns":"df","k":"const df = sl.dataset(\"penjualan\")\nsl.dataframe(df.sort_values(\"total\", { ascending: false }).head(5))"},{"g":"DataFrame","n":"nlargest","sig":"nlargest(n, kolom)","d":"n baris dengan nilai terbesar.","ns":"df","k":"const df = sl.dataset(\"penjualan\")\nsl.dataframe(df.nlargest(5, \"total\"))"},{"g":"DataFrame","n":"dropna","sig":"dropna({subset, how})","d":"Buang baris yang punya nilai kosong.","ns":"df","k":"const df = sl.dataset(\"data_kotor\")\nsl.write(df.length, \"→\", df.dropna().length, \"baris\")"},{"g":"DataFrame","n":"fillna","sig":"fillna(nilai | {kolom: nilai} | \"mean\" | \"ffill\")","d":"Isi nilai kosong.","ns":"df","k":"const df = sl.dataset(\"data_kotor\")\nsl.dataframe(df.fillna({ jumlah: 0, status: \"tidak diketahui\" }).head(5))"},{"g":"DataFrame","n":"drop_duplicates","sig":"drop_duplicates({subset, keep})","d":"Buang baris duplikat.","ns":"df","k":"const df = sl.dataset(\"data_kotor\")\nsl.write(df.length, \"→\", df.drop_duplicates().length, \"baris\")"},{"g":"DataFrame","n":"duplicated","sig":"duplicated({subset})","d":"Series benar/salah untuk baris duplikat.","ns":"df","k":"const df = sl.dataset(\"data_kotor\")\nsl.write(\"Duplikat:\", df.duplicated().sum())"},{"g":"DataFrame","n":"strip_strings","sig":"strip_strings()","d":"Rapikan spasi berlebih di semua kolom teks.","ns":"df","k":"const df = sl.dataset(\"data_kotor\")\nsl.dataframe(df.strip_strings().head(5))"},{"g":"DataFrame","n":"remove_outliers","sig":"remove_outliers(kolom, {method, k})","d":"Buang pencilan (IQR atau z-score).","ns":"df","k":"const df = sl.dataset(\"penjualan\")\nsl.write(df.length, \"→\", df.remove_outliers(\"total\").length, \"baris\")"},{"g":"DataFrame","n":"cap_outliers","sig":"cap_outliers(kolom, {method})","d":"Potong pencilan ke batas wajar (winsorizing).","ns":"df","k":"const df = sl.dataset(\"penjualan\")\nsl.write(\"Maks sebelum:\", df.total.max(), \"· sesudah:\", df.cap_outliers(\"total\").total.max())"},{"g":"DataFrame","n":"to_datetime","sig":"to_datetime(kolom, {format})","d":"Ubah kolom menjadi tanggal.","ns":"df","k":"const s = sl.to_datetime(sl.DataFrame({ t: [\"17/08/2024\", \"01/09/2024\"] }).t, { dayfirst: true })\nsl.write(s)"},{"g":"DataFrame","n":"to_numeric","sig":"to_numeric(kolom)","d":"Ubah kolom teks (\"Rp 1.250.000\") menjadi angka.","ns":"df","k":"const s = sl.to_numeric(sl.DataFrame({ harga: [\"Rp 15.000\", \"8.500\", \"-\"] }).harga)\nsl.write(s)"},{"g":"DataFrame","n":"groupby","sig":"groupby(kolom).agg({...})","d":"Kelompokkan lalu agregasi. Contoh agg bernama: `{ omzet: [\"total\", \"sum\"] }`.","ns":"df","k":"const df = sl.dataset(\"penjualan\")\nsl.dataframe(df.groupby(\"kota\").agg({ omzet: [\"total\", \"sum\"], transaksi: [\"id_transaksi\", \"nunique\"] }))"},{"g":"DataFrame","n":"pivot_table","sig":"pivot_table({index, columns, values, aggfunc, margins})","d":"Tabel pivot seperti di Excel.","ns":"df","k":"const df = sl.dataset(\"penjualan\")\nsl.dataframe(df.pivot_table({ index: \"kota\", columns: \"kanal\", values: \"total\", aggfunc: \"sum\" }))"},{"g":"DataFrame","n":"melt","sig":"melt({id_vars, value_vars})","d":"Ubah tabel lebar menjadi panjang.","ns":"df","k":"const df = sl.DataFrame([{ bulan: \"Jan\", online: 5, toko: 7 }, { bulan: \"Feb\", online: 6, toko: 4 }])\nsl.dataframe(df.melt({ id_vars: \"bulan\", var_name: \"kanal\", value_name: \"omzet\" }))"},{"g":"DataFrame","n":"merge","sig":"merge(kanan, {on, how})","d":"Gabung dengan tabel lain (JOIN).","ns":"df","k":"const jual = sl.DataFrame([{ produk: \"Kopi\", qty: 3 }, { produk: \"Teh\", qty: 5 }])\nconst harga = sl.DataFrame([{ produk: \"Kopi\", harga: 15000 }, { produk: \"Teh\", harga: 8000 }])\nsl.dataframe(sl.merge(jual, harga, { on: \"produk\", how: \"left\" }))"},{"g":"DataFrame","n":"resample","sig":"resample(kolom_tanggal, \"M\").agg({...})","d":"Kelompokkan per periode waktu (D, W, M, Q, Y).","ns":"df","k":"const df = sl.dataset(\"penjualan\")\nsl.line_chart(df.resample(\"tanggal\", \"M\").agg({ omzet: [\"total\", \"sum\"] }), { x: \"tanggal\", y: \"omzet\" })"},{"g":"DataFrame","n":"corr","sig":"corr({method})","d":"Matriks korelasi kolom angka (pearson/spearman).","ns":"df","k":"const df = sl.dataset(\"karyawan\")\nsl.dataframe(df.corr())"},{"g":"DataFrame","n":"crosstab","sig":"crosstab(a, b)","d":"Tabel silang dua kolom.","ns":"df","k":"const df = sl.dataset(\"penjualan\")\nsl.dataframe(sl.crosstab(df.kota, df.kanal))"},{"g":"DataFrame","n":"to_csv","sig":"to_csv({sep, decimal})","d":"Teks CSV.","ns":"df","k":"sl.code(sl.to_csv([{ kota: \"Jayapura\", omzet: 12 }, { kota: \"Sorong\", omzet: 8 }]))"},{"g":"DataFrame","n":"to_excel","sig":"to_excel(sheet)","d":"Berkas Excel (Blob).","ns":"df","k":"const df = sl.dataset(\"iris\")\nsl.download_button(\"Unduh Excel 2 lembar\", sl.to_excel({ Data: df, Ringkasan: df.describe() }), { file_name: \"iris.xlsx\" })"},{"g":"DataFrame","n":"to_records","sig":"to_records()","d":"Larik objek per baris.","ns":"df","k":"const df = sl.dataset(\"iris\").head(2)\nsl.json(df.to_records())"},{"g":"DataFrame","n":"to_markdown","sig":"to_markdown()","d":"Tabel Markdown untuk laporan.","ns":"df","k":"const df = sl.dataset(\"iris\").head(3)\nsl.markdown(df.to_markdown())"},{"g":"DataFrame","n":"get_dummies","sig":"get_dummies(kolom)","d":"One-hot encoding.","ns":"df","k":"sl.dataframe(sl.get_dummies(sl.dataset(\"penjualan\").select([\"kota\", \"total\"]).head(5), [\"kota\"]))"},{"g":"DataFrame","n":"apply","sig":"apply((baris) => nilai)","d":"Hitung satu nilai per baris (Series).","ns":"df","k":"const df = sl.dataset(\"penjualan\")\nsl.write(df.head(3).apply(r => `${r.produk}: ${r.jumlah} × ${r.harga}`))"},{"g":"Series (kolom)","n":"mean","sig":"kolom.mean()","d":"Rata-rata (sum, median, min, max, std, var, count juga ada).","ns":"df","k":"const df = sl.dataset(\"penjualan\")\nsl.metric(\"Rata-rata transaksi\", Math.round(df.total.mean()).toLocaleString(\"id-ID\"))"},{"g":"Series (kolom)","n":"quantile","sig":"kolom.quantile(q)","d":"Kuantil, mis. 0.9.","ns":"df","k":"const df = sl.dataset(\"penjualan\")\nsl.write(\"Persentil 90:\", df.total.quantile(0.9))"},{"g":"Series (kolom)","n":"str","sig":"kolom.str.lower() / .contains() / .replace()","d":"Operasi teks per nilai.","ns":"df","k":"const df = sl.dataset(\"penjualan\")\nsl.write(df.kota.str.upper().unique())"},{"g":"Series (kolom)","n":"dt","sig":"kolom.dt.year / .month / .day_name()","d":"Bagian tanggal.","ns":"df","k":"const df = sl.dataset(\"penjualan\")\nsl.bar_chart(df.tanggal.dt.month_name().value_counts())"},{"g":"Series (kolom)","n":"rolling","sig":"kolom.rolling(n).mean()","d":"Rata-rata bergerak.","ns":"df","k":"const df = sl.dataset(\"kunjungan_harian\")\nconst r = df.assign({ rata7: df.pengunjung.rolling(7).mean() })\nsl.line_chart(r.tail(90), { x: \"tanggal\", y: [\"pengunjung\", \"rata7\"] })"},{"g":"Series (kolom)","n":"pct_change","sig":"kolom.pct_change()","d":"Persentase perubahan dari baris sebelumnya.","ns":"df","k":"const df = sl.dataset(\"penjualan_bulanan\").tail(6)\nsl.dataframe(df.assign({ tumbuh: df.omzet_juta.pct_change() }))"},{"g":"Series (kolom)","n":"cumsum","sig":"kolom.cumsum()","d":"Jumlah kumulatif.","ns":"df","k":"const df = sl.dataset(\"penjualan_bulanan\").tail(12)\nsl.area_chart(df.assign({ kumulatif: df.omzet_juta.cumsum() }), { x: \"bulan\", y: \"kumulatif\" })"},{"g":"Series (kolom)","n":"rank","sig":"kolom.rank({ascending})","d":"Peringkat.","ns":"df","k":"const df = sl.dataset(\"karyawan\").head(5)\nsl.dataframe(df.assign({ peringkat: df.gaji_juta.rank({ ascending: false }) }).select([\"karyawan_id\", \"gaji_juta\", \"peringkat\"]))"},{"g":"Series (kolom)","n":"shift","sig":"kolom.shift(n)","d":"Geser n baris.","ns":"df","k":"const df = sl.dataset(\"penjualan_bulanan\").tail(4)\nsl.dataframe(df.assign({ bulan_lalu: df.omzet_juta.shift(1) }))"},{"g":"Series (kolom)","n":"map","sig":"kolom.map(fn | {lama: baru})","d":"Ubah setiap nilai.","ns":"df","k":"const kota = [\n  { kota: \"Jayapura\", lat: -2.53, lon: 140.72, omzet: 132 },\n  { kota: \"Sorong\", lat: -0.88, lon: 131.26, omzet: 73 },\n  { kota: \"Merauke\", lat: -8.49, lon: 140.40, omzet: 38 },\n  { kota: \"Timika\", lat: -4.55, lon: 136.89, omzet: 36 }\n]\nsl.map(kota, { lat: \"lat\", lon: \"lon\", size: \"omzet\", label: \"kota\" })"},{"g":"Series (kolom)","n":"between","sig":"kolom.between(a, b)","d":"Benar bila nilai di antara a dan b.","ns":"df","k":"const df = sl.dataset(\"penjualan\")\nsl.write(\"Transaksi 100–500 ribu:\", df.total.between(100000, 500000).sum())"},{"g":"Series (kolom)","n":"isin","sig":"kolom.isin([…])","d":"Benar bila nilai ada di daftar.","ns":"df","k":"const df = sl.dataset(\"penjualan\")\nsl.write(\"Transaksi di Sorong atau Biak:\", df.kota.isin([\"Sorong\", \"Biak\"]).sum())"},{"g":"Statistik (sl.stats)","n":"ttest_1samp","sig":"ttest_1samp(data, mu, {alternative})","d":"Uji-t satu sampel: apakah rata-rata berbeda dari nilai tertentu?","ns":"stats","k":"const df = sl.dataset(\"nilai_ujian\")\nsl.write(sl.stats.ttest_1samp(df.nilai_sesudah, 75))"},{"g":"Statistik (sl.stats)","n":"ttest_ind","sig":"ttest_ind(df, {value, group}) | (a, b)","d":"Uji-t dua kelompok independen (Welch).","ns":"stats","k":"const df = sl.dataset(\"ab_test\")\nsl.write(sl.stats.ttest_ind(df, { value: \"nilai_belanja\", group: \"grup\" }))"},{"g":"Statistik (sl.stats)","n":"ttest_rel","sig":"ttest_rel(sebelum, sesudah)","d":"Uji-t berpasangan.","ns":"stats","k":"const df = sl.dataset(\"nilai_ujian\")\nsl.write(sl.stats.ttest_rel(df.nilai_sebelum, df.nilai_sesudah))"},{"g":"Statistik (sl.stats)","n":"mannwhitneyu","sig":"mannwhitneyu(df, {value, group})","d":"Alternatif nonparametrik uji-t independen.","ns":"stats","k":"const df = sl.dataset(\"ab_test\")\nsl.write(sl.stats.mannwhitneyu(df, { value: \"nilai_belanja\", group: \"grup\" }))"},{"g":"Statistik (sl.stats)","n":"wilcoxon","sig":"wilcoxon(sebelum, sesudah)","d":"Alternatif nonparametrik uji-t berpasangan.","ns":"stats","k":"const df = sl.dataset(\"nilai_ujian\")\nsl.write(sl.stats.wilcoxon(df.nilai_sebelum, df.nilai_sesudah))"},{"g":"Statistik (sl.stats)","n":"f_oneway","sig":"f_oneway(df, {value, group})","d":"ANOVA satu arah: membandingkan rata-rata 3+ kelompok.","ns":"stats","k":"const df = sl.dataset(\"nilai_ujian\")\nsl.write(sl.stats.f_oneway(df, { value: \"nilai_sesudah\", group: \"metode\" }))"},{"g":"Statistik (sl.stats)","n":"pairwise_ttests","sig":"pairwise_ttests(df, {value, group, correction})","d":"Uji lanjutan ANOVA: setiap pasangan kelompok, dengan koreksi Holm.","ns":"stats","k":"const df = sl.dataset(\"nilai_ujian\")\nsl.write(sl.stats.pairwise_ttests(df, { value: \"nilai_sesudah\", group: \"metode\" }))"},{"g":"Statistik (sl.stats)","n":"kruskal","sig":"kruskal(df, {value, group})","d":"Alternatif nonparametrik ANOVA.","ns":"stats","k":"const df = sl.dataset(\"nilai_ujian\")\nsl.write(sl.stats.kruskal(df, { value: \"nilai_sesudah\", group: \"metode\" }))"},{"g":"Statistik (sl.stats)","n":"chi2_contingency","sig":"chi2_contingency(df, kolomA, kolomB)","d":"Uji hubungan dua variabel kategori, dengan Cramér's V.","ns":"stats","k":"const df = sl.dataset(\"pelanggan\")\nsl.write(sl.stats.chi2_contingency(df, \"paket\", \"churn\"))"},{"g":"Statistik (sl.stats)","n":"corr","sig":"corr(x, y, \"pearson\"|\"spearman\"|\"kendall\")","d":"Korelasi beserta p-value dan interval kepercayaan.","ns":"stats","k":"const df = sl.dataset(\"karyawan\")\nsl.write(sl.stats.corr(df.pengalaman_tahun, df.gaji_juta))"},{"g":"Statistik (sl.stats)","n":"shapiro","sig":"shapiro(data)","d":"Uji normalitas Shapiro-Wilk.","ns":"stats","k":"const df = sl.dataset(\"karyawan\")\nsl.write(sl.stats.shapiro(df.gaji_juta))"},{"g":"Statistik (sl.stats)","n":"levene","sig":"levene(df, {value, group})","d":"Uji kesamaan varians.","ns":"stats","k":"const df = sl.dataset(\"nilai_ujian\")\nsl.write(sl.stats.levene(df, { value: \"nilai_sesudah\", group: \"metode\" }))"},{"g":"Statistik (sl.stats)","n":"ab_test","sig":"ab_test(df, {group, metric, control})","d":"Uji A/B lengkap: konversi, lift, interval, p-value, dan daya uji.","ns":"stats","k":"const df = sl.dataset(\"ab_test\")\nsl.write(sl.stats.ab_test(df, { group: \"grup\", metric: \"beli\" }))"},{"g":"Statistik (sl.stats)","n":"proportions_ztest","sig":"proportions_ztest([k1, k2], [n1, n2])","d":"Uji-z satu atau dua proporsi.","ns":"stats","k":"sl.write(sl.stats.proportions_ztest([120, 150], [1000, 1000]))"},{"g":"Statistik (sl.stats)","n":"sample_size_proportion","sig":"sample_size_proportion(p1, mde, {power, alpha, relative})","d":"Ukuran sampel per grup untuk uji A/B.","ns":"stats","k":"sl.write(\"Pengunjung per grup:\", sl.stats.sample_size_proportion(0.10, 0.02))"},{"g":"Statistik (sl.stats)","n":"ci_mean","sig":"ci_mean(data, 0.95)","d":"Interval kepercayaan rata-rata.","ns":"stats","k":"const df = sl.dataset(\"penjualan\")\nsl.write(sl.stats.ci_mean(df.total))"},{"g":"Statistik (sl.stats)","n":"ci_proportion","sig":"ci_proportion(k, n)","d":"Interval kepercayaan proporsi (Wilson).","ns":"stats","k":"sl.write(sl.stats.ci_proportion(45, 300))"},{"g":"Statistik (sl.stats)","n":"bootstrap_ci","sig":"bootstrap_ci(data, \"median\", {n_boot})","d":"Interval kepercayaan dengan bootstrap.","ns":"stats","k":"const df = sl.dataset(\"penjualan\")\nsl.write(sl.stats.bootstrap_ci(df.total, \"median\"))"},{"g":"Statistik (sl.stats)","n":"ols","sig":"ols(df, \"y ~ x1 + x2 + C(kategori)\")","d":"Regresi linear berganda: koefisien, p-value, R², VIF, diagnostik.","ns":"stats","k":"const df = sl.dataset(\"karyawan\")\nsl.write(sl.stats.ols(df, \"gaji_juta ~ pengalaman_tahun + C(pendidikan)\"))"},{"g":"Statistik (sl.stats)","n":"logit","sig":"logit(df, \"y ~ x1 + x2\")","d":"Regresi logistik dengan p-value dan odds ratio.","ns":"stats","k":"const df = sl.dataset(\"pelanggan\")\nsl.write(sl.stats.logit(df, \"churn ~ lama_berlangganan + jumlah_keluhan\"))"},{"g":"Statistik (sl.stats)","n":"linregress","sig":"linregress(x, y)","d":"Regresi satu variabel: slope, intercept, r, p.","ns":"stats","k":"const df = sl.dataset(\"karyawan\")\nsl.write(sl.stats.linregress(df.pengalaman_tahun, df.gaji_juta))"},{"g":"Statistik (sl.stats)","n":"multipletests","sig":"multipletests(pvalues, \"holm\"|\"bonferroni\"|\"fdr_bh\")","d":"Koreksi banyak uji.","ns":"stats","k":"sl.write(sl.stats.multipletests([0.01, 0.04, 0.03, 0.20]))"},{"g":"Statistik (sl.stats)","n":"norm","sig":"norm.cdf / .ppf / .pdf","d":"Distribusi normal (juga t, chi2, f, binom).","ns":"stats","k":"sl.write({ z_975: sl.stats.norm.ppf(0.975), p_z196: sl.stats.norm.cdf(1.96) })"},{"g":"Machine learning (sl.ml)","n":"train_test_split","sig":"train_test_split(df, {test_size, seed, stratify})","d":"Bagi data menjadi latih dan uji. Mengembalikan [latih, uji].","ns":"ml","k":"const df = sl.dataset(\"iris\")\nconst X = df.drop(\"spesies\"), y = df.spesies\nconst [X_latih, X_uji, y_latih, y_uji] = sl.ml.train_test_split(X, y, { test_size: 0.3, random_state: 1 })\nsl.write(`Latih: ${X_latih.length} baris · Uji: ${X_uji.length} baris`)"},{"g":"Machine learning (sl.ml)","n":"LinearRegression","sig":"LinearRegression()","d":"Regresi linear. `.fit(X, y)`, `.predict(X)`, `.score(X, y)`.","ns":"ml","k":"const df = sl.dataset(\"karyawan\")\nconst X = df.select([\"pengalaman_tahun\", \"jam_pelatihan\", \"nilai_kinerja\"]), y = df.gaji_juta\nconst [X_latih, X_uji, y_latih, y_uji] = sl.ml.train_test_split(X, y, { test_size: 0.3, random_state: 1 })\nconst m = new sl.ml.LinearRegression().fit(X_latih, y_latih)\nsl.write(m)\nsl.metric(\"R² uji\", m.score(X_uji, y_uji).toFixed(3))"},{"g":"Machine learning (sl.ml)","n":"LogisticRegression","sig":"LogisticRegression({C})","d":"Klasifikasi logistik. `.predict_proba(X)` untuk probabilitas.","ns":"ml","k":"const df = sl.dataset(\"pelanggan\")\nconst X = df.select([\"umur\", \"lama_berlangganan\", \"tagihan_bulanan\", \"jumlah_keluhan\"]), y = df.churn\nconst [X_latih, X_uji, y_latih, y_uji] = sl.ml.train_test_split(X, y, { test_size: 0.3, random_state: 1 })\nconst m = new sl.ml.LogisticRegression().fit(X_latih, y_latih)\nsl.metric(\"Akurasi\", (m.score(X_uji, y_uji) * 100).toFixed(1) + \"%\")"},{"g":"Machine learning (sl.ml)","n":"DecisionTreeClassifier","sig":"DecisionTreeClassifier({max_depth})","d":"Pohon keputusan; `.rules()` menampilkan aturannya.","ns":"ml","k":"const df = sl.dataset(\"iris\")\nconst X = df.drop(\"spesies\"), y = df.spesies\nconst [X_latih, X_uji, y_latih, y_uji] = sl.ml.train_test_split(X, y, { test_size: 0.3, random_state: 1 })\nconst m = new sl.ml.DecisionTreeClassifier({ max_depth: 3 }).fit(X_latih, y_latih)\nsl.write(m)"},{"g":"Machine learning (sl.ml)","n":"RandomForestClassifier","sig":"RandomForestClassifier({n_estimators, max_depth})","d":"Hutan acak untuk klasifikasi; `.importances()` untuk kepentingan fitur.","ns":"ml","k":"const df = sl.dataset(\"pelanggan\")\nconst X = df.select([\"umur\", \"lama_berlangganan\", \"tagihan_bulanan\", \"jumlah_keluhan\"]), y = df.churn\nconst [X_latih, X_uji, y_latih, y_uji] = sl.ml.train_test_split(X, y, { test_size: 0.3, random_state: 1 })\nconst m = new sl.ml.RandomForestClassifier({ n_estimators: 50, random_state: 1 }).fit(X_latih, y_latih)\nsl.write(m)"},{"g":"Machine learning (sl.ml)","n":"RandomForestRegressor","sig":"RandomForestRegressor({n_estimators})","d":"Hutan acak untuk regresi.","ns":"ml","k":"const df = sl.dataset(\"karyawan\")\nconst X = df.select([\"pengalaman_tahun\", \"jam_pelatihan\", \"nilai_kinerja\"]), y = df.gaji_juta\nconst [X_latih, X_uji, y_latih, y_uji] = sl.ml.train_test_split(X, y, { test_size: 0.3, random_state: 1 })\nconst m = new sl.ml.RandomForestRegressor({ n_estimators: 50, random_state: 1 }).fit(X_latih, y_latih)\nsl.metric(\"R² uji\", m.score(X_uji, y_uji).toFixed(3))"},{"g":"Machine learning (sl.ml)","n":"KNeighborsClassifier","sig":"KNeighborsClassifier({n_neighbors})","d":"Klasifikasi tetangga terdekat.","ns":"ml","k":"const df = sl.dataset(\"iris\")\nconst X = df.drop(\"spesies\"), y = df.spesies\nconst [X_latih, X_uji, y_latih, y_uji] = sl.ml.train_test_split(X, y, { test_size: 0.3, random_state: 1 })\nconst m = new sl.ml.KNeighborsClassifier({ n_neighbors: 5 }).fit(X_latih, y_latih)\nsl.metric(\"Akurasi\", (m.score(X_uji, y_uji) * 100).toFixed(1) + \"%\")"},{"g":"Machine learning (sl.ml)","n":"GaussianNB","sig":"GaussianNB()","d":"Naive Bayes Gaussian.","ns":"ml","k":"const df = sl.dataset(\"iris\")\nconst X = df.drop(\"spesies\"), y = df.spesies\nconst [X_latih, X_uji, y_latih, y_uji] = sl.ml.train_test_split(X, y, { test_size: 0.3, random_state: 1 })\nconst m = new sl.ml.GaussianNB().fit(X_latih, y_latih)\nsl.metric(\"Akurasi\", (m.score(X_uji, y_uji) * 100).toFixed(1) + \"%\")"},{"g":"Machine learning (sl.ml)","n":"KMeans","sig":"KMeans({n_clusters})","d":"Klaster k-means. `.fit_predict(X)` mengembalikan label klaster.","ns":"ml","k":"const df = sl.dataset(\"iris\")\nconst km = new sl.ml.KMeans({ n_clusters: 3, random_state: 1 }).fit(df.drop(\"spesies\"))\nsl.scatter_chart(df.assign({ klaster: km.labels_.map(String) }), { x: \"panjang_mahkota\", y: \"lebar_mahkota\", by: \"klaster\" })"},{"g":"Machine learning (sl.ml)","n":"elbow","sig":"elbow(X, {k_max})","d":"Tabel inersia dan silhouette untuk memilih jumlah klaster.","ns":"ml","k":"const df = sl.dataset(\"iris\")\nsl.write(sl.ml.elbow(df.drop(\"spesies\"), { k_max: 8 }))"},{"g":"Machine learning (sl.ml)","n":"PCA","sig":"PCA({n_components})","d":"Reduksi dimensi; `.explained_variance_ratio_`.","ns":"ml","k":"const df = sl.dataset(\"iris\")\nconst pca = new sl.ml.PCA({ n_components: 2 }).fit(df.drop(\"spesies\"))\nconst Z = pca.transform(df.drop(\"spesies\"))\nsl.scatter_chart(Z.assign({ spesies: df.spesies }), { x: Z.columns[0], y: Z.columns[1], by: \"spesies\" })"},{"g":"Machine learning (sl.ml)","n":"StandardScaler","sig":"StandardScaler()","d":"Standarisasi kolom angka (rata-rata 0, simpangan 1).","ns":"ml","k":"const df = sl.dataset(\"karyawan\").select([\"gaji_juta\", \"jam_pelatihan\"])\nsl.dataframe(new sl.ml.StandardScaler().fit_transform(df).describe())"},{"g":"Machine learning (sl.ml)","n":"cross_validate","sig":"cross_validate(model, df, target, {cv, scoring})","d":"Validasi silang k-fold: skor tiap lipatan, rata-rata, dan simpangan.","ns":"ml","k":"const df = sl.dataset(\"pelanggan\")\nconst X = df.select([\"umur\", \"lama_berlangganan\", \"tagihan_bulanan\", \"jumlah_keluhan\"]), y = df.churn\nconst [X_latih, X_uji, y_latih, y_uji] = sl.ml.train_test_split(X, y, { test_size: 0.3, random_state: 1 })\nsl.write(sl.ml.cross_validate(new sl.ml.LogisticRegression(), X, y, { cv: 5 }))"},{"g":"Machine learning (sl.ml)","n":"accuracy_score","sig":"accuracy_score(aktual, prediksi)","d":"Akurasi.","ns":"ml","k":"const df = sl.dataset(\"iris\")\nconst X = df.drop(\"spesies\"), y = df.spesies\nconst [X_latih, X_uji, y_latih, y_uji] = sl.ml.train_test_split(X, y, { test_size: 0.3, random_state: 1 })\nconst p = new sl.ml.GaussianNB().fit(X_latih, y_latih).predict(X_uji)\nsl.metric(\"Akurasi\", sl.ml.accuracy_score(y_uji, p).toFixed(3))"},{"g":"Machine learning (sl.ml)","n":"classification_report","sig":"classification_report(aktual, prediksi)","d":"Precision, recall, F1 per kelas.","ns":"ml","k":"const df = sl.dataset(\"iris\")\nconst X = df.drop(\"spesies\"), y = df.spesies\nconst [X_latih, X_uji, y_latih, y_uji] = sl.ml.train_test_split(X, y, { test_size: 0.3, random_state: 1 })\nconst p = new sl.ml.GaussianNB().fit(X_latih, y_latih).predict(X_uji)\nsl.write(sl.ml.classification_report(y_uji, p))"},{"g":"Machine learning (sl.ml)","n":"confusion_matrix","sig":"confusion_matrix(aktual, prediksi)","d":"Matriks kebingungan (tampilkan dengan heatmap).","ns":"ml","k":"const df = sl.dataset(\"iris\")\nconst X = df.drop(\"spesies\"), y = df.spesies\nconst [X_latih, X_uji, y_latih, y_uji] = sl.ml.train_test_split(X, y, { test_size: 0.3, random_state: 1 })\nconst p = new sl.ml.GaussianNB().fit(X_latih, y_latih).predict(X_uji)\nsl.write(sl.ml.confusion_matrix(y_uji, p))"},{"g":"Machine learning (sl.ml)","n":"roc_auc_score","sig":"roc_auc_score(aktual, skor)","d":"Luas di bawah kurva ROC.","ns":"ml","k":"const df = sl.dataset(\"pelanggan\")\nconst X = df.select([\"umur\", \"lama_berlangganan\", \"tagihan_bulanan\", \"jumlah_keluhan\"]), y = df.churn\nconst [X_latih, X_uji, y_latih, y_uji] = sl.ml.train_test_split(X, y, { test_size: 0.3, random_state: 1 })\nconst prob = new sl.ml.LogisticRegression().fit(X_latih, y_latih).predict_proba(X_uji)\nsl.metric(\"AUC\", sl.ml.roc_auc_score(y_uji, prob).toFixed(3))"},{"g":"Machine learning (sl.ml)","n":"roc_curve","sig":"roc_curve(aktual, skor)","d":"Titik kurva ROC (fpr, tpr).","ns":"ml","k":"const df = sl.dataset(\"pelanggan\")\nconst X = df.select([\"umur\", \"lama_berlangganan\", \"tagihan_bulanan\", \"jumlah_keluhan\"]), y = df.churn\nconst [X_latih, X_uji, y_latih, y_uji] = sl.ml.train_test_split(X, y, { test_size: 0.3, random_state: 1 })\nconst prob = new sl.ml.LogisticRegression().fit(X_latih, y_latih).predict_proba(X_uji)\nsl.write(sl.ml.roc_curve(y_uji, prob))"},{"g":"Machine learning (sl.ml)","n":"r2_score","sig":"r2_score(aktual, prediksi)","d":"Koefisien determinasi.","ns":"ml","k":"const df = sl.dataset(\"karyawan\")\nconst X = df.select([\"pengalaman_tahun\", \"jam_pelatihan\", \"nilai_kinerja\"]), y = df.gaji_juta\nconst [X_latih, X_uji, y_latih, y_uji] = sl.ml.train_test_split(X, y, { test_size: 0.3, random_state: 1 })\nconst p = new sl.ml.LinearRegression().fit(X_latih, y_latih).predict(X_uji)\nsl.metric(\"R²\", sl.ml.r2_score(y_uji, p).toFixed(3))"},{"g":"Machine learning (sl.ml)","n":"mean_absolute_error","sig":"mean_absolute_error(aktual, prediksi)","d":"MAE (juga rmse, mape).","ns":"ml","k":"const df = sl.dataset(\"karyawan\")\nconst X = df.select([\"pengalaman_tahun\", \"jam_pelatihan\", \"nilai_kinerja\"]), y = df.gaji_juta\nconst [X_latih, X_uji, y_latih, y_uji] = sl.ml.train_test_split(X, y, { test_size: 0.3, random_state: 1 })\nconst p = new sl.ml.LinearRegression().fit(X_latih, y_latih).predict(X_uji)\nsl.metric(\"MAE (juta)\", sl.ml.mean_absolute_error(y_uji, p).toFixed(2))"},{"g":"Deret waktu (sl.ts)","n":"forecast","sig":"forecast(df, {date, value, periods, method})","d":"Peramalan dengan pemilihan metode otomatis (SES, Holt, Holt-Winters) beserta interval.","ns":"ts","k":"const df = sl.dataset(\"penjualan_bulanan\")\nsl.write(sl.ts.forecast(df, { periods: 12 }))"},{"g":"Deret waktu (sl.ts)","n":"decompose","sig":"decompose(df, {period, model})","d":"Pisahkan tren, musiman, dan residu.","ns":"ts","k":"const df = sl.dataset(\"penjualan_bulanan\")\nsl.write(sl.ts.decompose(df, { period: 12 }))"},{"g":"Deret waktu (sl.ts)","n":"acf","sig":"acf(series, nlags)","d":"Autokorelasi untuk melihat pola berulang.","ns":"ts","k":"const df = sl.dataset(\"kunjungan_harian\")\nsl.bar_chart(sl.ts.acf(df.pengunjung, 21), { x: \"lag\", y: \"acf\" })"},{"g":"Analisis bisnis (sl.analysis)","n":"cohort","sig":"cohort(df, {customer, date, period, metric})","d":"Tabel retensi kohort. Tampilkan dengan heatmap.","ns":"analysis","k":"const df = sl.dataset(\"penjualan\")\nsl.write(sl.analysis.cohort(df, { customer: \"pelanggan_id\", date: \"tanggal\" }))"},{"g":"Analisis bisnis (sl.analysis)","n":"rfm","sig":"rfm(df, {customer, date, amount})","d":"Skor Recency-Frequency-Monetary dan segmen pelanggan.","ns":"analysis","k":"const df = sl.dataset(\"penjualan\")\nsl.write(sl.analysis.rfm(df, { customer: \"pelanggan_id\", date: \"tanggal\", amount: \"total\" }))"},{"g":"Analisis bisnis (sl.analysis)","n":"funnel","sig":"funnel({Tahap: jumlah, …})","d":"Konversi tiap tahap corong.","ns":"analysis","k":"sl.write(sl.analysis.funnel({ Kunjungan: 10000, Keranjang: 1200, Bayar: 300 }))"},{"g":"Analisis bisnis (sl.analysis)","n":"pareto","sig":"pareto(df, {category, value})","d":"Analisis Pareto/ABC (80/20).","ns":"analysis","k":"const df = sl.dataset(\"penjualan\")\nsl.write(sl.analysis.pareto(df, { category: \"produk\", value: \"total\" }))"},{"g":"Analisis bisnis (sl.analysis)","n":"growth","sig":"growth(df, {date, value, period})","d":"Pertumbuhan per periode (MoM/YoY) dan kumulatif.","ns":"analysis","k":"const df = sl.dataset(\"penjualan\")\nsl.write(sl.analysis.growth(df, { date: \"tanggal\", value: \"total\" }))"},{"g":"Peta","n":"map","sig":"map(data, {lat, lon, region, size, color, label, tooltip, cluster, heatmap, route, to_lat, to_lon, tiles, layers, on_select})","d":"Peta titik, gelembung, klaster, heatmap, dan rute. Tanpa lat/lon, nama wilayah di kolom `region` dicarikan koordinatnya (514 kab/kota, 38 provinsi). Peta dasar luring; titik di luar Indonesia tampil di atas batas negara bila `slak-peta-dunia.js` dimuat. `tiles: \"osm\"` memakai ubin daring dengan peta luring sebagai cadangan. Klik titik dengan `on_select: \"rerun\"`.","k":"const kota = [\n  { kota: \"Jayapura\", lat: -2.53, lon: 140.72, omzet: 132 },\n  { kota: \"Sorong\", lat: -0.88, lon: 131.26, omzet: 73 },\n  { kota: \"Merauke\", lat: -8.49, lon: 140.40, omzet: 38 },\n  { kota: \"Timika\", lat: -4.55, lon: 136.89, omzet: 36 }\n]\nsl.map(kota, { lat: \"lat\", lon: \"lon\", size: \"omzet\", label: \"kota\" })"},{"g":"Peta","n":"choropleth","sig":"choropleth(data, {region, value, level, agg, colors, bins, labels, geojson, feature_key, on_select})","d":"Mewarnai wilayah menurut nilai. Nama provinsi/kab/kota dikenali otomatis (singkatan seperti Jabar, NTT, Jaksel; nama lama; salah ketik ringan). `level`: \"provinsi\" atau \"kabkota\". `bins: 5` membuat kelas kuantil. `geojson` untuk batas sendiri.","k":"const df = sl.DataFrame([{ provinsi: \"Papua\", omzet: 132 }, { provinsi: \"Papua Barat Daya\", omzet: 73 }, { provinsi: \"Papua Selatan\", omzet: 38 }, { provinsi: \"Papua Tengah\", omzet: 36 }])\nsl.choropleth(df, { region: \"provinsi\", value: \"omzet\", labels: true })"},{"g":"Peta","n":"read_geojson","sig":"await read_geojson(berkas | url | objek)","d":"Membaca GeoJSON atau TopoJSON untuk dipakai di map/choropleth (`geojson`).","k":"const gj = await sl.read_geojson('{\"type\":\"FeatureCollection\",\"features\":[{\"type\":\"Feature\",\"properties\":{\"nama\":\"Kotak\"},\"geometry\":{\"type\":\"Polygon\",\"coordinates\":[[[140,-3],[141,-3],[141,-2],[140,-2],[140,-3]]]}}]}')\nsl.map(null, { layers: [{ geojson: gj, label: \"nama\" }] })"},{"g":"Peta","n":"geo","sig":"geo.<fungsi>(…)","d":"Alat bantu geografis: jarak, geocode nama wilayah, provinsi dari koordinat, titik terdekat. Ketik `sl.geo.`.","k":"sl.write(\"Jarak Jayapura–Sorong:\", Math.round(sl.geo.distance(-2.53, 140.72, -0.88, 131.26)), \"km\")"},{"g":"Peta (sl.geo)","n":"distance","sig":"distance(lat1, lon1, lat2, lon2)","d":"Jarak lingkaran besar dalam kilometer. Bisa juga distance({lat, lon}, {lat, lon}).","ns":"geo","k":"sl.metric(\"Jarak Jayapura–Sorong\", Math.round(sl.geo.distance(-2.53, 140.72, -0.88, 131.26)) + \" km\")"},{"g":"Peta (sl.geo)","n":"geocode","sig":"geocode(df, kolom, {level})","d":"Menambahkan kolom wilayah_baku, lat, lon dari nama wilayah.","ns":"geo","k":"const df = sl.DataFrame([{ kota: \"Jayapura\" }, { kota: \"Timika\" }, { kota: \"Merauke\" }])\nsl.dataframe(sl.geo.geocode(df, \"kota\"))"},{"g":"Peta (sl.geo)","n":"match","sig":"match(nama, {level})","d":"Mencocokkan satu nama wilayah ke nama baku, provinsi, dan koordinat.","ns":"geo","k":"sl.write(sl.geo.match(\"Timika\"), sl.geo.match(\"Jabar\"))"},{"g":"Peta (sl.geo)","n":"centroid","sig":"centroid(nama)","d":"Titik tengah wilayah: {lat, lon}.","ns":"geo","k":"sl.write(sl.geo.centroid(\"Papua Tengah\"))"},{"g":"Peta (sl.geo)","n":"province_of","sig":"province_of(lat, lon)","d":"Nama provinsi tempat titik berada.","ns":"geo","k":"sl.write(\"Titik ini ada di provinsi:\", sl.geo.province_of(-2.53, 140.72))"},{"g":"Peta (sl.geo)","n":"kabkota_of","sig":"kabkota_of(lat, lon)","d":"Nama kab/kota tempat titik berada (memuat batas kab/kota).","ns":"geo","k":"await sl.geo.load_kabkota()\nsl.write(\"Titik ini ada di:\", sl.geo.kabkota_of(-4.09, 138.95))"},{"g":"Peta (sl.geo)","n":"contains","sig":"contains(wilayah, lat, lon)","d":"Benar bila titik berada di dalam wilayah (nama atau GeoJSON).","ns":"geo","k":"sl.write(\"Denpasar di Bali?\", sl.geo.contains(\"Bali\", -8.65, 115.22))"},{"g":"Peta (sl.geo)","n":"nearest","sig":"nearest(df, lat, lon, {k})","d":"Baris terdekat dari sebuah titik, dengan kolom jarak_km.","ns":"geo","k":"const kota = [\n  { kota: \"Jayapura\", lat: -2.53, lon: 140.72, omzet: 132 },\n  { kota: \"Sorong\", lat: -0.88, lon: 131.26, omzet: 73 },\n  { kota: \"Merauke\", lat: -8.49, lon: 140.40, omzet: 38 },\n  { kota: \"Timika\", lat: -4.55, lon: 136.89, omzet: 36 }\n]\nsl.dataframe(sl.geo.nearest(kota, -3.0, 139.0, { k: 2 }))"},{"g":"Peta (sl.geo)","n":"provinces","sig":"provinces()","d":"Daftar 38 provinsi: kode, nama, ISO, titik tengah.","ns":"geo","k":"sl.dataframe(sl.geo.provinces().head(6))"},{"g":"Peta (sl.geo)","n":"kabkota","sig":"kabkota(provinsi?)","d":"Daftar 514 kab/kota (bisa disaring per provinsi).","ns":"geo","k":"sl.dataframe(sl.geo.kabkota(\"Papua Selatan\"))"},{"g":"Peta (sl.geo)","n":"to_geojson","sig":"to_geojson(df, {lat, lon})","d":"Mengubah tabel berkoordinat menjadi GeoJSON titik.","ns":"geo","k":"const kota = [\n  { kota: \"Jayapura\", lat: -2.53, lon: 140.72, omzet: 132 },\n  { kota: \"Sorong\", lat: -0.88, lon: 131.26, omzet: 73 },\n  { kota: \"Merauke\", lat: -8.49, lon: 140.40, omzet: 38 },\n  { kota: \"Timika\", lat: -4.55, lon: 136.89, omzet: 36 }\n]\nsl.json(sl.geo.to_geojson(kota))"},{"g":"Peta (sl.geo)","n":"boundaries","sig":"boundaries(\"provinsi\" | \"kabkota\")","d":"Batas wilayah bawaan sebagai GeoJSON.","ns":"geo","k":"const b = sl.geo.boundaries(\"provinsi\")\nsl.write(b.features.length, \"provinsi\")"},{"g":"Peta (sl.geo)","n":"load_kabkota","sig":"await load_kabkota()","d":"Memuat batas kab/kota bila belum dimuat.","ns":"geo","k":"await sl.geo.load_kabkota()\nsl.write(\"Batas kab/kota siap dipakai.\")"},{"g":"Teks","n":"badge","sig":"badge(label, {icon, color})","d":"Lencana kecil berwarna. `color`: red, orange, yellow, blue, green, violet, gray, primary.","k":"sl.badge(\"Baru\", { icon: \":sparkles:\", color: \"green\" })\nsl.badge(\"Stok menipis\", { icon: \":warning:\", color: \"orange\" })\nsl.badge(\"Habis\", { color: \"red\" })"},{"g":"Teks","n":"latex","sig":"latex(rumus)","d":"Menampilkan rumus matematika LaTeX tanpa internet: pecahan, akar, sigma, integral, matriks, dan lainnya.","k":"sl.latex(\"\\\\bar{x} = \\\\frac{1}{n}\\\\sum_{i=1}^{n} x_i\")\nsl.markdown(\"Rumus di dalam teks: $E = mc^2$\")"},{"g":"Teks","n":"echo","sig":"echo(() => { ... }, {code_location})","d":"Menampilkan kode di dalam fungsi, lalu menjalankannya. Cocok untuk tutorial.","k":"sl.echo(() => {\n  const n = 5\n  sl.write(`Kuadrat dari ${n} adalah ${n * n}`)\n})"},{"g":"Teks","n":"help","sig":"help(objek)","d":"Menampilkan jenis, properti, dan fungsi sebuah objek, misalnya DataFrame.","k":"const df = sl.dataset(\"iris\")\nsl.help(df)"},{"g":"Teks","n":"write_stream","sig":"await write_stream(teks | generator | stream)","d":"Menulis teks mengalir seperti mesin ketik. Menerima teks, generator (juga async), atau aliran dari fetch. Mengembalikan teks lengkap.","k":"await sl.write_stream(\"Halo! Teks ini muncul kata demi kata, seperti jawaban chatbot.\")"},{"g":"Teks","n":"iframe","sig":"iframe(url | html, {height, width})","d":"Menyematkan halaman lain atau potongan HTML di dalam bingkai.","k":"sl.iframe(\"<h3 style='font-family:sans-serif'>Halaman kecil di dalam bingkai</h3><p>Bisa juga alamat https://…</p>\", { height: 140 })"},{"g":"Media","n":"pdf","sig":"pdf(src, {height})","d":"Menampilkan PDF dari URL, berkas unggahan, atau data biner.","k":"const f = sl.file_uploader(\"Pilih PDF\", { type: \"pdf\" })\nif (f) sl.pdf(f, { height: 500 })\nelse sl.caption(\"Unggah berkas PDF untuk melihatnya di sini.\")"},{"g":"Media","n":"logo","sig":"logo(gambar, {link, icon_image, size})","d":"Logo di pojok kiri atas dan di sidebar.","k":"sl.logo(\"data:image/svg+xml;utf8,\" + encodeURIComponent('<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"600\" height=\"220\"><rect width=\"600\" height=\"220\" fill=\"#0f766e\"/><text x=\"300\" y=\"125\" font-size=\"42\" text-anchor=\"middle\" fill=\"white\" font-family=\"sans-serif\">Gambar contoh</text></svg>'), { link: \"https://example.com\" })\nsl.write(\"Logo tampil di pojok kiri atas.\")"},{"g":"Tata letak","n":"space","sig":"space(ukuran)","d":"Jarak kosong: \"small\", \"medium\", \"large\", atau angka piksel.","k":"sl.write(\"Atas\")\nsl.space(\"large\")\nsl.write(\"Bawah, setelah ruang kosong\")"},{"g":"Tata letak","n":"popover","sig":"popover(label, {icon, type, width}, fn)","d":"Tombol yang membuka panel melayang berisi elemen apa pun.","k":"sl.popover(\"Pengaturan :gear:\", (p) => {\n  p.checkbox(\"Tampilkan detail\")\n  p.slider(\"Jumlah baris\", 5, 50, 10)\n})"},{"g":"Tata letak","n":"bottom","sig":"bottom.<fungsi>(…)","d":"Area yang menempel di bawah layar, seperti tempat chat_input.","k":"sl.write(\"Isi halaman…\")\nsl.bottom.caption(\"Teks ini menempel di bagian bawah layar.\")"},{"g":"Tata letak","n":"dialog","sig":"const buka = dialog(judul, (sl, ...arg) => {...}, {width, dismissible, on_dismiss})","d":"Jendela modal. Panggil fungsi yang dikembalikan untuk membukanya. Widget di dalam dialog hanya menjalankan ulang dialog; `sl.rerun()` menutupnya.","k":"const ubah = sl.dialog(\"Ubah data\", (sl, nama) => {\n  sl.write(`Mengubah **${nama}**`)\n  if (sl.button(\"Simpan\")) sl.rerun()\n})\nif (sl.button(\"Ubah Ani\")) ubah(\"Ani\")"},{"g":"Tata letak","n":"fragment","sig":"const f = fragment((sl, ...arg) => {...}, {run_every, key}); f()","d":"Bagian yang bisa jalan ulang sendiri tanpa menjalankan seluruh skrip. `run_every: 5` menjalankannya ulang setiap 5 detik (untuk data yang terus berubah).","k":"const jam = sl.fragment((sl) => {\n  sl.metric(\"Jam\", new Date().toLocaleTimeString(\"id-ID\"))\n}, { run_every: 1 })\njam()"},{"g":"Status","n":"status","sig":"status(label, {state, expanded}, fn)","d":"Kotak status untuk proses panjang. `state`: \"running\", \"complete\", \"error\". Ubah dengan `.update({label, state})`; dengan fungsi async, status otomatis selesai.","k":"await sl.status(\"Memuat data…\", async (s) => {\n  s.write(\"Membaca berkas…\")\n  await sl.sleep(400)\n  s.write(\"Menghitung ringkasan…\")\n  await sl.sleep(400)\n}, { state: \"complete\", expanded: true })"},{"g":"Status","n":"skeleton","sig":"skeleton({height}) atau await skeleton(async () => {...})","d":"Kotak berkilau sebagai penanda isi yang sedang dimuat. Isinya diganti saat placeholder diisi.","k":"const tempat = sl.skeleton({ height: 120 })\nawait sl.sleep(1000)\ntempat.success(\"Data sudah siap.\")"},{"g":"Status","n":"snow","sig":"snow()","d":"Animasi salju perayaan.","k":"if (sl.button(\"Turunkan salju :snowflake:\")) sl.snow()"},{"g":"Widget","n":"pills","sig":"pills(label, opsi, {selection_mode, default, format_func})","d":"Pilihan berbentuk tombol bulat. `selection_mode: \"multi\"` untuk banyak pilihan.","k":"const kat = sl.pills(\"Kategori\", [\"Makanan\", \"Minuman\", \"Snack\"], { selection_mode: \"multi\", default: [\"Makanan\"] })\nsl.write(\"Dipilih:\", kat)"},{"g":"Widget","n":"segmented_control","sig":"segmented_control(label, opsi, {selection_mode, default})","d":"Pilihan berupa tombol yang menyatu, cocok untuk 2–5 mode.","k":"const periode = sl.segmented_control(\"Periode\", [\"Harian\", \"Mingguan\", \"Bulanan\"], { default: \"Mingguan\" })\nsl.write(\"Periode:\", periode)"},{"g":"Widget","n":"feedback","sig":"feedback(\"thumbs\" | \"faces\" | \"stars\", {key})","d":"Umpan balik: jempol (1 suka, 0 tidak), wajah (0–4), atau bintang (0–4). Mengembalikan null bila belum dipilih.","k":"const bintang = sl.feedback(\"stars\")\nif (bintang != null) sl.write(`Terima kasih atas ${bintang + 1} bintang!`)"},{"g":"Widget","n":"menu_button","sig":"menu_button(label, opsi, {icon, type, on_click})","d":"Tombol dengan daftar pilihan. Mengembalikan opsi yang diklik pada jalan ulang itu, selain itu null.","k":"const pilihan = sl.menu_button(\"Ekspor\", [\"CSV\", \"Excel\", \"PDF\"], { icon: \":material/download:\" })\nif (pilihan) sl.toast(\"Mengekspor \" + pilihan)"},{"g":"Widget","n":"pagination","sig":"pagination(jumlah_halaman, {default, max_visible_pages})","d":"Penomoran halaman. Mengembalikan nomor halaman (mulai 1).","k":"const df = sl.dataset(\"penjualan\")\nconst hal = sl.pagination(Math.ceil(df.length / 10))\nsl.dataframe(df.slice((hal - 1) * 10, hal * 10), { hide_index: true })"},{"g":"Widget","n":"datetime_input","sig":"datetime_input(label, nilai, {min_value, max_value})","d":"Input tanggal dan jam. Mengembalikan teks \"YYYY-MM-DD HH:MM\".","k":"const w = sl.datetime_input(\"Waktu janji\")\nsl.write(\"Janji:\", w)"},{"g":"Widget","n":"camera_input","sig":"camera_input(label)","d":"Ambil foto dari kamera. Mengembalikan berkas (.url, .bytes, .name) atau null.","k":"const foto = sl.camera_input(\"Foto produk\")\nif (foto) sl.image(foto)"},{"g":"Widget","n":"audio_input","sig":"audio_input(label, {sample_rate})","d":"Rekam suara dari mikrofon. Hasilnya berkas WAV (.url, .bytes) atau null.","k":"const suara = sl.audio_input(\"Rekam catatan suara\")\nif (suara) sl.audio(suara)"},{"g":"Grafik","n":"plotly_chart","sig":"plotly_chart({data, layout}, {height, on_select})","d":"Grafik Plotly interaktif. Pustaka diunduh dari internet saat pertama dipakai.","k":"sl.plotly_chart({\n  data: [{ x: [\"Jayapura\", \"Sorong\", \"Merauke\"], y: [12, 8, 5], type: \"bar\" }],\n  layout: { title: \"Omzet (juta)\" }\n})","online":1},{"g":"Grafik","n":"echarts_chart","sig":"echarts_chart(opsi, {height, on_select})","d":"Grafik Apache ECharts. Pustaka diunduh dari internet saat pertama dipakai.","k":"sl.echarts_chart({\n  xAxis: { type: \"category\", data: [\"Sen\", \"Sel\", \"Rab\", \"Kam\", \"Jum\"] },\n  yAxis: {},\n  series: [{ type: \"line\", smooth: true, data: [120, 200, 150, 80, 170] }]\n})","online":1},{"g":"Grafik","n":"mermaid_chart","sig":"mermaid_chart(teks)","d":"Diagram Mermaid (alur, urutan, gantt). Butuh internet saat pertama dipakai.","k":"sl.mermaid_chart(\"graph LR; Data --> Bersihkan --> Analisis --> Laporan\")","online":1},{"g":"Grafik","n":"graphviz_chart","sig":"graphviz_chart(dot)","d":"Diagram Graphviz dari bahasa DOT. Butuh internet saat pertama dipakai.","k":"sl.graphviz_chart(\"digraph { rankdir=LR; Pesanan -> Gudang -> Kurir -> Pelanggan }\")","online":1},{"g":"Grafik","n":"vega_lite_chart","sig":"vega_lite_chart(data, spec)","d":"Spesifikasi Vega-Lite (mark bar, line, area, point, arc, rect) digambar oleh mesin grafik Slak tanpa internet. Juga sebagai `altair_chart`.","k":"const df = sl.dataset(\"penjualan\")\nsl.vega_lite_chart(df, { mark: \"bar\", encoding: { x: { field: \"kota\" }, y: { field: \"total\", aggregate: \"sum\" } } })"},{"g":"SQL & Python","n":"pyplot","sig":"await pyplot(kode, { df: tabel })","d":"Menjalankan kode matplotlib di Python lalu menampilkan grafiknya. Butuh internet saat pertama kali dimuat.","k":"const df = sl.dataset(\"penjualan\")\nawait sl.pyplot(`\nplt.figure(figsize=(7, 3.5))\nplt.hist(df.total / 1000, bins=20, color=\"#0f766e\")\nplt.xlabel(\"Total transaksi (ribu rupiah)\")\nplt.ylabel(\"Jumlah transaksi\")`, { df })","online":1},{"g":"SQL & Python","n":"connection","sig":"connection(nama, {type: \"sql\", url})","d":"Padanan st.connection: database SQLite (tersimpan di browser, atau berkas .db lewat `url`). `await conn.query(sql, {params, ttl})` menghasilkan DataFrame.","k":"const conn = sl.connection(\"contoh_toko\", { type: \"sql\" })\nconst db = await conn.session\ndb.run(\"CREATE TABLE IF NOT EXISTS barang (nama TEXT, stok INT)\")\nif (!db.query(\"SELECT COUNT(*) n FROM barang\").n.values[0]) db.run(\"INSERT INTO barang VALUES ('Kopi', 12), ('Teh', 3)\")\nsl.dataframe(await conn.query(\"SELECT * FROM barang WHERE stok < :batas\", { params: { batas: 5 } }))"},{"g":"Logika","n":"cache_resource","sig":"cache_resource(fungsi, {ttl, max_entries})","d":"Menyimpan objek yang mahal dibuat (model, koneksi) dan dipakai bersama tanpa disalin.","k":"const model = sl.cache_resource(() => new sl.ml.KMeans({ n_clusters: 3 }))\nsl.write(\"Model dibuat sekali dan dipakai ulang:\", model().constructor.name)"},{"g":"Logika","n":"context","sig":"context.<nama>","d":"Info pengguna: `locale`, `timezone`, `timezone_offset`, `url`, `theme.type`, `is_embedded`, `cookies`.","k":"sl.write({ bahasa: sl.context.locale, zona_waktu: sl.context.timezone, tema: sl.context.theme.type })"},{"g":"Logika","n":"get_option","sig":"get_option(nama)","d":"Membaca opsi, misalnya \"theme.primaryColor\" atau \"client.toolbarMode\".","k":"sl.write(\"Warna utama:\", sl.get_option(\"theme.primaryColor\"))"},{"g":"Logika","n":"set_option","sig":"set_option(nama, nilai)","d":"Mengubah opsi: tema (\"theme.primaryColor\", \"theme.font\"…), \"client.toolbarMode\" (\"minimal\"), \"client.showSidebarNavigation\", \"client.disableDataExport\", \"client.showErrorDetails\", atau \"sql.portable\".","k":"sl.set_option(\"theme.primaryColor\", \"#7c3aed\")\nsl.button(\"Tombol berwarna ungu\", { type: \"primary\" })"},{"g":"Logika","n":"column_config","sig":"column_config.<Jenis>(label, {…})","d":"Jenis kolom untuk dataframe dan data_editor. Ketik `sl.column_config.`.","k":"const data = [{ produk: \"Kopi\", harga: 15000, terjual: 0.72 }, { produk: \"Teh\", harga: 8000, terjual: 0.35 }]\nsl.dataframe(data, { hide_index: true, column_config: {\n  harga: sl.column_config.NumberColumn(\"Harga\", { format: \"rp\" }),\n  terjual: sl.column_config.ProgressColumn(\"Target\", { min_value: 0, max_value: 1 })\n} })"},{"g":"Keamanan","n":"crypto","sig":"crypto.<fungsi>(…)","d":"Hash (md5, sha256), password (bcrypt), enkripsi AES, dan pelindung jawaban kuis. Ketik `sl.crypto.`.","k":"sl.write({ md5: sl.crypto.md5(\"halo\"), sha256: sl.crypto.sha256(\"halo\") })"},{"g":"Keamanan (sl.crypto)","n":"md5","sig":"md5(teks, {encoding})","d":"Sidik jari MD5 (32 karakter heksa). Cocok untuk memeriksa perubahan data, bukan untuk password.","ns":"crypto","k":"sl.code(sl.crypto.md5(\"halo\"))"},{"g":"Keamanan (sl.crypto)","n":"sha256","sig":"sha256(teks, {encoding})","d":"Hash SHA-256. Ada juga sha1, sha384, sha512. `encoding`: \"hex\", \"base64\", \"bytes\".","ns":"crypto","k":"sl.code(sl.crypto.sha256(\"halo\"))"},{"g":"Keamanan (sl.crypto)","n":"hmac","sig":"hmac(kunci, pesan, algoritma)","d":"Tanda tangan HMAC (bawaan sha256).","ns":"crypto","k":"sl.code(sl.crypto.hmac(\"kunci-rahasia\", \"pesan penting\"))"},{"g":"Keamanan (sl.crypto)","n":"hash_password","sig":"await hash_password(password, {cost})","d":"Hash password bcrypt ($2y$), cocok dengan password_hash() di PHP. Simpan hasilnya, jangan passwordnya.","ns":"crypto","k":"const h = await sl.crypto.hash_password(\"rahasia123\")\nsl.code(h)\nsl.caption(\"Hasilnya berbeda setiap kali, tetapi selalu cocok dengan password yang sama.\")"},{"g":"Keamanan (sl.crypto)","n":"verify_password","sig":"await verify_password(password, hash)","d":"Memeriksa password terhadap hash bcrypt. Mengembalikan true/false.","ns":"crypto","k":"const h = \"$2y$10$qlFsqVOQ2Fg.JoyEeObqGuxcui98Wciz2a5XQWUPHSKXffI4ng3sy\"   // hash dari \"rahasia\"\nconst pw = sl.text_input(\"Password\", { type: \"password\", value: \"rahasia\" })\nsl.write(await sl.crypto.verify_password(pw, h) ? \":white_check_mark: Cocok\" : \":x: Salah\")"},{"g":"Keamanan (sl.crypto)","n":"encrypt","sig":"await encrypt(teks, kata_sandi)","d":"Enkripsi AES-256-GCM dengan kata sandi. Jangan tulis kata sandinya di halaman yang sama.","ns":"crypto","k":"const terkunci = await sl.crypto.encrypt(\"Nilai rahasia: 87\", \"sandi-guru\")\nsl.code(terkunci)\nsl.write(\"Dibuka:\", await sl.crypto.decrypt(terkunci, \"sandi-guru\"))"},{"g":"Keamanan (sl.crypto)","n":"decrypt","sig":"await decrypt(data, kata_sandi)","d":"Membuka hasil encrypt(). Kata sandi salah menimbulkan galat.","ns":"crypto","k":"const terkunci = await sl.crypto.encrypt(\"Pesan rahasia\", \"sandi\")\nsl.write(await sl.crypto.decrypt(terkunci, \"sandi\"))"},{"g":"Keamanan (sl.crypto)","n":"quiz_hash","sig":"quiz_hash(jawaban | [jawaban…], {exact})","d":"Membuat kode pelindung jawaban kuis. Lebih mudah lewat menu Alat › Lindungi jawaban kuis.","ns":"crypto","k":"sl.code(sl.crypto.quiz_hash(\"fotosintesis\"))\nsl.caption(\"Tempel kode ini di soal kuis, bukan jawabannya.\")"},{"g":"Keamanan (sl.crypto)","n":"quiz_check","sig":"quiz_check(jawaban, kode)","d":"Mencocokkan jawaban dengan kode dari quiz_hash. Huruf besar/kecil, spasi lebih, dan titik di akhir diabaikan.","ns":"crypto","k":"const KUNCI = sl.crypto.quiz_hash(\"fotosintesis\")\nconst j = sl.text_input(\"Proses tumbuhan membuat makanan?\", { value: \"Fotosintesis\" })\nsl.write(sl.crypto.quiz_check(j, KUNCI) ? \":white_check_mark: Benar\" : \":x: Belum tepat\")"},{"g":"Keamanan (sl.crypto)","n":"random_token","sig":"random_token(jumlah_byte, {encoding})","d":"Token acak yang aman, misalnya untuk kode undangan.","ns":"crypto","k":"sl.code(sl.crypto.random_token(16))"},{"g":"Keamanan (sl.crypto)","n":"uuid","sig":"uuid()","d":"ID unik acak (UUID v4).","ns":"crypto","k":"sl.code(sl.crypto.uuid())"},{"g":"Keamanan (sl.crypto)","n":"base64","sig":"base64(teks)","d":"Mengubah teks menjadi Base64. Kebalikannya from_base64().","ns":"crypto","k":"sl.code(sl.crypto.base64(\"Halo, Slak!\"))"},{"g":"Keamanan (sl.crypto)","n":"from_base64","sig":"from_base64(teks)","d":"Mengubah Base64 kembali menjadi teks.","ns":"crypto","k":"sl.write(sl.crypto.from_base64(\"SGFsbywgU2xhayE=\"))"},{"g":"Jenis kolom (sl.column_config)","n":"TextColumn","sig":"TextColumn(label, {max_chars, validate, width, help, required, default, pinned})","d":"Kolom teks. `validate` berupa pola regex.","ns":"column_config","k":"const data = [{ nama: \"Ani Wenda\" }, { nama: \"Budi\" }]\nsl.dataframe(data, { hide_index: true, column_config: { nama: sl.column_config.TextColumn(\"Nama\", { max_chars: 50, help: \"Nama lengkap\" }) } })"},{"g":"Jenis kolom (sl.column_config)","n":"NumberColumn","sig":"NumberColumn(label, {min_value, max_value, step, format})","d":"Kolom angka. `format`: \"rp\", \"dollar\", \"percent\", \"compact\", atau printf \"%.2f\".","ns":"column_config","k":"const data = [{ harga: 15000 }, { harga: 8500 }]\nsl.dataframe(data, { hide_index: true, column_config: { harga: sl.column_config.NumberColumn(\"Harga\", { format: \"rp\", min_value: 0 }) } })"},{"g":"Jenis kolom (sl.column_config)","n":"CheckboxColumn","sig":"CheckboxColumn(label)","d":"Kolom ya/tidak.","ns":"column_config","k":"const data = [{ barang: \"Kopi\", aktif: true }, { barang: \"Teh\", aktif: false }]\nsl.dataframe(data, { hide_index: true, column_config: { aktif: sl.column_config.CheckboxColumn(\"Aktif\") } })"},{"g":"Jenis kolom (sl.column_config)","n":"SelectboxColumn","sig":"SelectboxColumn(label, {options})","d":"Pilih satu dari daftar.","ns":"column_config","k":"const data = [{ pesanan: 1, status: \"Baru\" }, { pesanan: 2, status: \"Selesai\" }]\nsl.dataframe(data, { hide_index: true, column_config: { status: sl.column_config.SelectboxColumn(\"Status\", { options: [\"Baru\", \"Proses\", \"Selesai\"] }) } })"},{"g":"Jenis kolom (sl.column_config)","n":"MultiselectColumn","sig":"MultiselectColumn(label, {options})","d":"Pilih beberapa dari daftar (nilai berupa larik).","ns":"column_config","k":"const data = [{ barang: \"Kopi\", tag: [\"promo\", \"baru\"] }]\nsl.dataframe(data, { hide_index: true, column_config: { tag: sl.column_config.MultiselectColumn(\"Tag\", { options: [\"promo\", \"baru\", \"habis\"] }) } })"},{"g":"Jenis kolom (sl.column_config)","n":"DateColumn","sig":"DateColumn(label, {format})","d":"Tanggal. `format` gaya \"DD MMM YYYY\", atau \"localized\", \"distance\".","ns":"column_config","k":"const data = [{ tanggal: new Date(2024, 7, 17) }]\nsl.dataframe(data, { hide_index: true, column_config: { tanggal: sl.column_config.DateColumn(\"Tanggal\", { format: \"DD MMM YYYY\" }) } })"},{"g":"Jenis kolom (sl.column_config)","n":"DatetimeColumn","sig":"DatetimeColumn(label, {format})","d":"Tanggal dan jam.","ns":"column_config","k":"const data = [{ waktu: new Date(2024, 7, 17, 9, 30) }]\nsl.dataframe(data, { hide_index: true, column_config: { waktu: sl.column_config.DatetimeColumn(\"Waktu\", { format: \"DD/MM HH:mm\" }) } })"},{"g":"Jenis kolom (sl.column_config)","n":"TimeColumn","sig":"TimeColumn(label, {format})","d":"Jam.","ns":"column_config","k":"const data = [{ buka: \"08:00\" }, { buka: \"09:30\" }]\nsl.dataframe(data, { hide_index: true, column_config: { buka: sl.column_config.TimeColumn(\"Jam buka\") } })"},{"g":"Jenis kolom (sl.column_config)","n":"LinkColumn","sig":"LinkColumn(label, {display_text})","d":"Tautan yang bisa diklik. `display_text` bisa teks tetap atau regex dengan grup.","ns":"column_config","k":"const data = [{ situs: \"https://example.com/toko\" }]\nsl.dataframe(data, { hide_index: true, column_config: { situs: sl.column_config.LinkColumn(\"Situs\", { display_text: \"Buka toko\" }) } })"},{"g":"Jenis kolom (sl.column_config)","n":"ImageColumn","sig":"ImageColumn(label)","d":"Menampilkan gambar dari URL.","ns":"column_config","k":"const data = [{ foto: \"data:image/svg+xml;utf8,\" + encodeURIComponent('<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"40\" height=\"40\"><circle cx=\"20\" cy=\"20\" r=\"18\" fill=\"#0f766e\"/></svg>') }]\nsl.dataframe(data, { hide_index: true, column_config: { foto: sl.column_config.ImageColumn(\"Foto\") } })"},{"g":"Jenis kolom (sl.column_config)","n":"ProgressColumn","sig":"ProgressColumn(label, {min_value, max_value, format})","d":"Bilah kemajuan per baris.","ns":"column_config","k":"const data = [{ toko: \"A\", target: 72 }, { toko: \"B\", target: 35 }]\nsl.dataframe(data, { hide_index: true, column_config: { target: sl.column_config.ProgressColumn(\"Target\", { min_value: 0, max_value: 100, format: \"%d%%\" }) } })"},{"g":"Jenis kolom (sl.column_config)","n":"LineChartColumn","sig":"LineChartColumn(label, {y_min, y_max})","d":"Grafik garis mini dari larik angka. Ada juga BarChartColumn dan AreaChartColumn.","ns":"column_config","k":"const data = [{ produk: \"Kopi\", tren: [3, 5, 4, 7, 9] }, { produk: \"Teh\", tren: [6, 4, 5, 3, 2] }]\nsl.dataframe(data, { hide_index: true, column_config: { tren: sl.column_config.LineChartColumn(\"Tren 5 hari\") } })"},{"g":"Jenis kolom (sl.column_config)","n":"BarChartColumn","sig":"BarChartColumn(label, {y_min, y_max})","d":"Grafik batang mini dari larik angka.","ns":"column_config","k":"const data = [{ produk: \"Kopi\", jual: [3, 5, 4, 7, 9] }]\nsl.dataframe(data, { hide_index: true, column_config: { jual: sl.column_config.BarChartColumn(\"Penjualan\") } })"},{"g":"Jenis kolom (sl.column_config)","n":"AreaChartColumn","sig":"AreaChartColumn(label, {y_min, y_max})","d":"Grafik area mini dari larik angka.","ns":"column_config","k":"const data = [{ produk: \"Kopi\", tren: [3, 5, 4, 7, 9] }]\nsl.dataframe(data, { hide_index: true, column_config: { tren: sl.column_config.AreaChartColumn(\"Tren\") } })"},{"g":"Jenis kolom (sl.column_config)","n":"ListColumn","sig":"ListColumn(label)","d":"Menampilkan larik sebagai label kecil.","ns":"column_config","k":"const data = [{ produk: \"Kopi\", kategori: [\"minuman\", \"panas\"] }]\nsl.dataframe(data, { hide_index: true, column_config: { kategori: sl.column_config.ListColumn(\"Kategori\") } })"},{"g":"Jenis kolom (sl.column_config)","n":"JsonColumn","sig":"JsonColumn(label)","d":"Menampilkan objek sebagai JSON.","ns":"column_config","k":"const data = [{ id: 1, data: { warna: \"merah\", ukuran: \"L\" } }]\nsl.dataframe(data, { hide_index: true, column_config: { data: sl.column_config.JsonColumn(\"Data\") } })"},{"g":"Jenis kolom (sl.column_config)","n":"MarkdownColumn","sig":"MarkdownColumn(label)","d":"Isi sel dibaca sebagai Markdown.","ns":"column_config","k":"const data = [{ catatan: \"**Penting**: kirim hari ini :truck:\" }]\nsl.dataframe(data, { hide_index: true, column_config: { catatan: sl.column_config.MarkdownColumn(\"Catatan\") } })"},{"g":"Jenis kolom (sl.column_config)","n":"ButtonColumn","sig":"ButtonColumn(label, {button_label})","d":"Tombol per baris (sl.dataframe). Klik → hasil memuat `clicked: {row, column}`.","ns":"column_config","k":"const data = [{ produk: \"Kopi\", aksi: \"Lihat\" }]\nsl.dataframe(data, { hide_index: true, column_config: { aksi: sl.column_config.ButtonColumn(\"Aksi\", { button_label: \"Lihat\" }) } })"},{"g":"Jenis kolom (sl.column_config)","n":"AudioColumn","sig":"AudioColumn(label)","d":"Pemutar audio per baris.","ns":"column_config","k":"const data = [{ rekaman: \"https://upload.wikimedia.org/wikipedia/commons/c/c8/Example.ogg\" }]\nsl.dataframe(data, { hide_index: true, column_config: { rekaman: sl.column_config.AudioColumn(\"Rekaman\") } })"},{"g":"Jenis kolom (sl.column_config)","n":"VideoColumn","sig":"VideoColumn(label)","d":"Pemutar video per baris.","ns":"column_config","k":"const data = [{ video: \"https://example.com/video.mp4\" }]\nsl.dataframe(data, { hide_index: true, column_config: { video: sl.column_config.VideoColumn(\"Video\") } })"},{"g":"Jenis kolom (sl.column_config)","n":"Column","sig":"Column(label, {width, help, disabled, required, pinned, hidden, alignment})","d":"Pengaturan umum kolom tanpa mengubah jenisnya.","ns":"column_config","k":"const data = [{ kode: \"A-01\", nama: \"Kopi\" }]\nsl.dataframe(data, { hide_index: true, column_config: { kode: sl.column_config.Column(\"Kode\", { pinned: true, width: \"small\" }) } })"},{"g":"Info pengguna (sl.context)","n":"locale","sig":"locale","d":"Bahasa browser, misalnya \"id-ID\".","ns":"context","k":"sl.write(\"sl.context.locale =\", sl.context.locale)"},{"g":"Info pengguna (sl.context)","n":"timezone","sig":"timezone","d":"Zona waktu pengguna, misalnya \"Asia/Jayapura\".","ns":"context","k":"sl.write(\"sl.context.timezone =\", sl.context.timezone)"},{"g":"Info pengguna (sl.context)","n":"timezone_offset","sig":"timezone_offset","d":"Selisih dari UTC dalam menit (seperti getTimezoneOffset).","ns":"context","k":"sl.write(\"sl.context.timezone_offset =\", sl.context.timezone_offset)"},{"g":"Info pengguna (sl.context)","n":"url","sig":"url","d":"Alamat halaman saat ini.","ns":"context","k":"sl.write(\"sl.context.url =\", sl.context.url)"},{"g":"Info pengguna (sl.context)","n":"theme","sig":"theme.type","d":"Tema yang sedang tampil: \"light\" atau \"dark\".","ns":"context","k":"sl.write(\"Tema:\", sl.context.theme.type)"},{"g":"Info pengguna (sl.context)","n":"is_embedded","sig":"is_embedded","d":"true bila halaman berada di dalam iframe.","ns":"context","k":"sl.write(\"sl.context.is_embedded =\", sl.context.is_embedded)"},{"g":"Info pengguna (sl.context)","n":"cookies","sig":"cookies","d":"Cookie halaman sebagai objek.","ns":"context","k":"sl.write(\"sl.context.cookies =\", sl.context.cookies)"},{"g":"SQL (sl.sql)","n":"check","sig":"sql.check(kueri)","d":"Daftar sintaks khusus SQLite di kueri beserta padanan PostgreSQL-nya.","ns":"sql","k":"sl.dataframe(sl.sql.check(\"SELECT IFNULL(total, 0), strftime('%Y', tanggal) FROM jual\"))"},{"g":"SQL (sl.sql)","n":"to_sqlite","sig":"sql.to_sqlite(kueri)","d":"Melihat hasil penulisan ulang sintaks PostgreSQL ke SQLite.","ns":"sql","k":"sl.code(sl.sql.to_sqlite(\"SELECT tanggal::date, date_trunc('month', tanggal) FROM jual WHERE kota ILIKE '%pura'\"), \"sql\")"},{"g":"SQL (sl.sql)","n":"tables","sig":"await sql.tables()","d":"Daftar tabel yang sedang dimuat di sl.sql.","ns":"sql","k":"await sl.sql(\"SELECT 1\", { jual: sl.dataset(\"penjualan\") })\nsl.dataframe(await sl.sql.tables())"},{"g":"SQL (sl.sql)","n":"reset","sig":"sql.reset()","d":"Mengosongkan database sementara sl.sql.","ns":"sql","k":"sl.sql.reset()\nsl.write(\"Semua tabel sementara sl.sql dihapus.\")"},{"g":"Slak 1.3.2","n":"bungkus data","sig":"Alat → Bungkus data…","d":"Mengubah `data.csv` (juga .xlsx, .json, .db) menjadi `data.csv.js` di sebelahnya. Halaman yang dibuka dengan klik dua kali boleh memuat berkas .js, jadi `read_csv(\"data.csv\")` tetap jalan tanpa server dan tanpa mengubah kode. Di luar Studio: buka `bungkus.html`.","k":"// penjualan.csv.js (hasil Alat › Bungkus data) ada di folder yang sama\n// const df = await sl.read_csv(\"penjualan.csv\")\nSlak.files[\"contoh.csv\"] = \"kota,n\\nJayapura,3\\nSorong,5\"   // sama seperti isi berkas .js\nsl.dataframe(await sl.read_csv(\"contoh.csv\"))"},{"g":"Slak 1.3.2","n":"data di dalam halaman","sig":"<script type=\"text/csv\" id=\"nama.csv\">","d":"Data kecil bisa ditulis langsung di HTML. `read_csv(\"nama.csv\")` menemukannya. Ekspor HTML Slak Studio menyematkan data dengan cara ini secara otomatis.","k":"// Di HTML, tulis data di dalam tag script dengan type=\"text/csv\" dan id=\"kota.csv\".\n// Cara di bawah ini setara:\nSlak.files[\"kota.csv\"] = \"kota,n\\nJayapura,3\\nMerauke,2\"\nsl.dataframe(await sl.read_csv(\"kota.csv\"))"},{"g":"Slak 1.3.2","n":"slak-peta-dunia.js","sig":"<script src=\"slak-peta-dunia.js\">","d":"Batas 242 negara dan provinsi/negara bagian AS, Kanada, Brasil, Australia, Rusia, India, Tiongkok, Afrika Selatan (Natural Earth, domain publik, 600 KB). Dipakai otomatis untuk titik di luar Indonesia. Slak Studio menyertakannya saat ekspor bila peta memakai koordinat.","k":"// Muat slak-peta-dunia.js sesudah slak-peta.js\nsl.map([{ kota: \"New York\", lat: 40.7, lon: -74 }, { kota: \"London\", lat: 51.5, lon: -0.1 }, { kota: \"Jayapura\", lat: -2.5, lon: 140.7 }], { label: \"kota\" })"},{"g":"Slak 1.3.2","n":"Slak.wrap_file","sig":"Slak.wrap_file(nama, isi)","d":"Membuat teks berkas pembungkus (.js) dari isi berkas (teks atau Uint8Array). Dipakai oleh bungkus.html.","k":"const js = Slak.wrap_file(\"kota.csv\", \"kota,n\\nJayapura,3\")\nsl.code(js, \"javascript\")\nsl.download_button(\"Unduh kota.csv.js\", js, { file_name: \"kota.csv.js\" })"},{"g":"Login & pengguna","n":"login","sig":"await login({users, title, caption, register, remember, days, show_user, on_login})","d":"Menampilkan formulir masuk dan menghentikan skrip sampai pengguna masuk. `users` berisi nama pengguna, password (hash bcrypt dari Alat › Lindungi password), `name`, dan `role`. Bisa juga larik, DataFrame, atau fungsi yang mengambil dari sl.db/SQLite. `register: true` menambah tab Daftar. Login ini berjalan di browser: cocok untuk memisahkan tampilan per peran, bukan untuk melindungi data rahasia.","k":"const user = await sl.login({\n  users: {\n    ani:  { password: \"$2y$10$qlFsqVOQ2Fg.JoyEeObqGuxcui98Wciz2a5XQWUPHSKXffI4ng3sy\", name: \"Ani\", role: \"admin\" },   // password: rahasia\n    budi: { password: \"$2y$10$1CqnlJsbMyNlswHM.h5IJO3XSrqx5dBpnknnMT4Sb/2wV/yyP0uEa\", name: \"Budi\", role: \"kasir\" }  // password: admin123\n  },\n  title: \":convenience_store: Toko Maju\"\n})\nsl.success(`Selamat datang, ${user.name}!`)"},{"g":"Login & pengguna","n":"user","sig":"user","d":"Info pengguna yang sedang masuk: `is_logged_in`, `username`, `name`, `role`, `roles`, dan `has_role(\"admin\")`.","k":"const user = await sl.login({\n  users: {\n    ani:  { password: \"$2y$10$qlFsqVOQ2Fg.JoyEeObqGuxcui98Wciz2a5XQWUPHSKXffI4ng3sy\", name: \"Ani\", role: \"admin\" },   // password: rahasia\n    budi: { password: \"$2y$10$1CqnlJsbMyNlswHM.h5IJO3XSrqx5dBpnknnMT4Sb/2wV/yyP0uEa\", name: \"Budi\", role: \"kasir\" }  // password: admin123\n  },\n  title: \":convenience_store: Toko Maju\"\n})\nsl.json(sl.user)"},{"g":"Login & pengguna","n":"logout","sig":"logout()","d":"Keluar, lalu aplikasi dijalankan ulang ke formulir masuk. Tombol \"Keluar\" juga muncul otomatis di sidebar.","k":"const user = await sl.login({\n  users: {\n    ani:  { password: \"$2y$10$qlFsqVOQ2Fg.JoyEeObqGuxcui98Wciz2a5XQWUPHSKXffI4ng3sy\", name: \"Ani\", role: \"admin\" },   // password: rahasia\n    budi: { password: \"$2y$10$1CqnlJsbMyNlswHM.h5IJO3XSrqx5dBpnknnMT4Sb/2wV/yyP0uEa\", name: \"Budi\", role: \"kasir\" }  // password: admin123\n  },\n  title: \":convenience_store: Toko Maju\"\n})\nsl.write(`Masuk sebagai **${sl.user.name}**`)\nif (sl.button(\"Keluar\")) sl.logout()"},{"g":"Login & pengguna","n":"require_role","sig":"require_role(...peran)","d":"Menghentikan halaman dengan pesan bila pengguna tidak punya salah satu peran itu.","k":"const user = await sl.login({\n  users: {\n    ani:  { password: \"$2y$10$qlFsqVOQ2Fg.JoyEeObqGuxcui98Wciz2a5XQWUPHSKXffI4ng3sy\", name: \"Ani\", role: \"admin\" },   // password: rahasia\n    budi: { password: \"$2y$10$1CqnlJsbMyNlswHM.h5IJO3XSrqx5dBpnknnMT4Sb/2wV/yyP0uEa\", name: \"Budi\", role: \"kasir\" }  // password: admin123\n  },\n  title: \":convenience_store: Toko Maju\"\n})\nsl.title(\"Laporan keuangan\")\nsl.require_role(\"admin\")\nsl.write(\"Hanya admin yang melihat bagian ini.\")"},{"g":"Ikon & emoji","n":"emoji","sig":"emoji(nama) · emoji.search(kata) · emoji.names() · emoji.icons()","d":"Emoji dari namanya, tanpa salin-tempel gambar. Tiga jenis nama: nama Streamlit (`:rocket:`, 1.570 nama), nama resmi Indonesia dari Unicode CLDR (`:kantung_uang:`), dan alias pendek (`:uang:`, `:senyum:`). Di teks cukup tulis `:nama:`. `emoji.icons()` mendaftar ~250 ikon `:material/...:` yang tampil tanpa internet.","k":"sl.title(\"Laporan :bar_chart: :kantung_uang: :senyum:\")\nsl.write(sl.emoji(\"rocket\"), sl.emoji(\"uang\"))\nsl.dataframe(sl.emoji.search(\"uang\", { limit: 5 }), { hide_index: true })"},{"g":"Dataset online","n":"read_url","sig":"await read_url(url, {file, ttl, refresh, parse})","d":"Membaca CSV, TSV, JSON, Excel, atau zip dari internet. Hasilnya disimpan di browser (7 hari, atur dengan `ttl`), jadi tetap jalan saat luring.","k":"const df = await sl.read_url(\"https://raw.githubusercontent.com/mwaskom/seaborn-data/master/tips.csv\")\nsl.dataframe(df.head())","online":1},{"g":"Dataset online","n":"github","sig":"await github(\"pemilik/repo/jalur.csv\", {ref, ttl})","d":"Berkas data di GitHub. Bisa juga alamat https://github.com/…/blob/…. Cabang lain: `\"pemilik/repo@cabang/jalur.csv\"`.","k":"const df = await sl.github(\"plotly/datasets/2014_usa_states.csv\")\nsl.bar_chart(df.nlargest(10, \"Population\"), { x: \"State\", y: \"Population\", horizontal: true })","online":1},{"g":"Dataset online","n":"huggingface","sig":"await huggingface(\"org/dataset\", {file, revision})","d":"Dataset Hugging Face. Tanpa `file`, berkas CSV/JSON pertama yang dipilih.","k":"const df = await sl.huggingface(\"scikit-learn/iris\", { file: \"Iris.csv\" })\nsl.dataframe(df.head())","online":1},{"g":"Dataset online","n":"worldbank","sig":"await worldbank(indikator, {negara, tahun, wide})","d":"Indikator Bank Dunia per negara dan tahun, misalnya `NY.GDP.PCAP.CD` (PDB per kapita), `SP.POP.TOTL` (penduduk). Negara memakai kode ISO-3 (IDN, MYS).","k":"const df = await sl.worldbank(\"NY.GDP.PCAP.CD\", { negara: [\"IDN\", \"MYS\", \"THA\"], tahun: [2000, 2023] })\nsl.line_chart(df, { x: \"tahun\", y: \"nilai\", by: \"negara\", title: \"PDB per kapita (US$)\" })","online":1},{"g":"Dataset online","n":"kaggle","sig":"await kaggle(\"pemilik/dataset\", {file})","d":"Dataset Kaggle. Di Slak Studio diunduh langsung (dataset privat butuh kaggle.json). Di browser biasa, Kaggle tidak mengizinkan unduhan langsung: Slak meminta berkas zip hasil unduhan manual dan mengingatnya.","k":"const df = await sl.kaggle(\"uciml/iris\", { file: \"Iris.csv\" })\nsl.dataframe(df.head())","online":1},{"g":"Dataset online","n":"open_data","sig":"await open_data(id) · open_data.list() · open_data.search(kata)","d":"Katalog dataset terbuka pilihan (penguins, co2, gapminder, iris, tips, titanic, gempa, …) lengkap dengan lisensinya.","k":"sl.dataframe(sl.open_data.list(), { hide_index: true })\nconst df = await sl.open_data(\"penguins\")\nsl.scatter_chart(df.dropna(), { x: \"flipper_length_mm\", y: \"body_mass_g\", by: \"species\" })","online":1},{"g":"Dataset online","n":"offline_button","sig":"offline_button({label})","d":"Tombol unduh untuk setiap dataset online yang dimuat, dalam bentuk berkas .js. Taruh di folder halaman agar aplikasi jalan tanpa internet dan saat dibuka dengan klik dua kali.","k":"const df = await sl.open_data(\"tips\")\nsl.dataframe(df.head())\nsl.offline_button()   // unduh tips.csv.js agar jalan tanpa internet","online":1},{"g":"DuckDB","n":"duckdb","sig":"await duckdb(sql, {nama: DataFrame})","d":"SQL analitik yang sangat cepat untuk data besar (jutaan baris), langsung di browser. Bisa membaca berkas yang disebut di SQL (`'penjualan.parquet'`, `'data.csv'`) dan DataFrame yang dikirim sebagai tabel. Hasilnya DataFrame. Butuh slak-duckdb.js; mesinnya (±35 MB) diunduh saat pertama dipakai, kecuali di Slak Studio.","k":"// Satu juta transaksi dibuat langsung oleh DuckDB, lalu dirangkum dalam sekejap\nconst df = await sl.duckdb(`\n  WITH jual AS (\n    SELECT (['Jayapura','Sorong','Merauke','Timika','Biak'])[1 + i % 5] AS kota,\n           10000 + (i * 7919) % 990000 AS total\n    FROM range(1000000) t(i))\n  SELECT kota, COUNT(*) AS transaksi, SUM(total) AS omzet\n  FROM jual GROUP BY kota ORDER BY omzet DESC`)\nsl.bar_chart(df, { x: \"kota\", y: \"omzet\", horizontal: true, format: \"compact\" })\nsl.dataframe(df, { hide_index: true })"},{"g":"DuckDB","n":"read_parquet","sig":"await read_parquet(berkas, {columns, nrows})","d":"Membaca berkas Parquet (format data kolom yang ringkas dan cepat) menjadi DataFrame. Berkas bisa berupa nama, URL, Uint8Array, atau hasil file_uploader.","k":"const df = sl.dataset(\"penjualan\")\n// Simpan sebagai Parquet, lalu baca kembali\nconst pq = await sl.duckdb.to_file(\"SELECT * FROM jual\", \"penjualan.parquet\", { jual: df })\nconst balik = await sl.read_parquet(pq)\nsl.write(`Parquet: ${(pq.length / 1024).toFixed(0)} KB · ${balik.length} baris`)\nsl.dataframe(balik.head())"},{"g":"DuckDB","n":"to_file","sig":"await duckdb.to_file(sql, \"nama.parquet\", {tabel})","d":"Menyimpan hasil kueri sebagai berkas Parquet, CSV, atau JSON (Uint8Array) untuk download_button. Parquet biasanya 5–10 kali lebih kecil dari CSV.","ns":"duckdb","k":"const df = sl.dataset(\"penjualan\")\nconst pq = await sl.duckdb.to_file(\"SELECT kota, produk, total FROM jual WHERE total > 500000\", \"transaksi_besar.parquet\", { jual: df })\nsl.download_button(\"Unduh Parquet\", pq, { file_name: \"transaksi_besar.parquet\" })\nsl.caption(`${(pq.length / 1024).toFixed(1)} KB`)"},{"g":"DuckDB","n":"version","sig":"await duckdb.version()","d":"Versi mesin DuckDB yang dipakai.","ns":"duckdb","k":"sl.write(\"Mesin DuckDB:\", await sl.duckdb.version())"},{"g":"Slak Data","n":"limits","sig":"limits = { nyaman, berat }","d":"Batas ukuran data (jumlah baris) yang memicu peringatan. Bawaan: nyaman 100.000 baris, berat 1.000.000 baris, hasil pengukuran Slak 1.6 (Bab 32). Di atas batas nyaman, Slak menampilkan saran memakai DuckDB atau SQL. Isi `Infinity` untuk mematikan peringatan.","ns":"data","k":"// Peringatan muncul bila data melewati batas nyaman (bawaan 100.000 baris)\nsl.data.limits.nyaman = 1000            // contoh: turunkan agar peringatan terlihat\nconst df = await sl.read_csv(sl.dataset(\"penjualan\").to_csv())   // 3.278 baris\nsl.write(\"Jumlah baris:\", df.length)\nsl.caption(\"Lihat peringatan di pojok kanan atas. Kembalikan dengan sl.data.limits.nyaman = 100000.\")"},{"g":"Statistik","n":"binom.sf","sig":"binom.sf(k, n, p)","d":"Peluang lebih dari k keberhasilan dari n percobaan, P(X > k). Pasangan dari binom.pmf dan binom.cdf.","ns":"stats","k":"// Peluang lebih dari 3 pembeli dari 10 pengunjung, bila peluang membeli 30%\nconst lebih = sl.stats.binom.sf(3, 10, 0.3)\nsl.metric(\"P(X > 3)\", (lebih * 100).toFixed(1) + \"%\")\nconst k = [...Array(11).keys()]\nsl.bar_chart({ pembeli: k, peluang: k.map(i => sl.stats.binom.pmf(i, 10, 0.3)) }, { x: \"pembeli\", y: \"peluang\" })"},{"g":"SQL & Python","n":"connection","sig":"connection(nama, {type: \"bridge\", url, database, key, dev_url})","d":"Membaca dan menulis MySQL/MariaDB, PostgreSQL, atau SQLite di server lewat **slak-bridge.php** (cPanel) atau **slak-bridge.js** (Node.js). Password database tinggal di server. `await db.query(sql, {params, ttl})` → DataFrame; `await db.execute(sql, params)` → {rowCount, lastInsertId}; `await db.run(\"nama_kueri\", params)` untuk kueri bernama; `db.tables()`, `db.table(nama)`. Bawaannya hanya-baca; mode tulis diatur di berkas jembatan. Buat berkasnya dari jendela Database: klik kanan koneksi › Pakai di kode Slak › Buat slak-bridge.php. `dev_url` dipakai di pratinjau Slak Studio dan halaman klik dua kali.","k":"const conn = sl.connection(\"contoh_toko\", { type: \"sql\" })\nconst db = await conn.session\ndb.run(\"CREATE TABLE IF NOT EXISTS barang (nama TEXT, stok INT)\")\nif (!db.query(\"SELECT COUNT(*) n FROM barang\").n.values[0]) db.run(\"INSERT INTO barang VALUES ('Kopi', 12), ('Teh', 3)\")\nsl.dataframe(await conn.query(\"SELECT * FROM barang WHERE stok < :batas\", { params: { batas: 5 } }))"},{"g":"SQL & Python","n":"connection","sig":"connection(nama, {type: \"turso\", url, token})","d":"Database libSQL/Turso (SQLite di cloud), dibaca langsung dari browser tanpa jembatan. Pakai token hanya-baca (`turso db tokens create nama-db --read-only`), karena token di halaman bisa dibaca pengunjung. Metode sama dengan tipe bridge.","k":"const conn = sl.connection(\"contoh_toko\", { type: \"sql\" })\nconst db = await conn.session\ndb.run(\"CREATE TABLE IF NOT EXISTS barang (nama TEXT, stok INT)\")\nif (!db.query(\"SELECT COUNT(*) n FROM barang\").n.values[0]) db.run(\"INSERT INTO barang VALUES ('Kopi', 12), ('Teh', 3)\")\nsl.dataframe(await conn.query(\"SELECT * FROM barang WHERE stok < :batas\", { params: { batas: 5 } }))"},{"g":"Uji aplikasi","n":"run","sig":"await testing.run(kode | \"berkas.slak\" | fungsi, {timeout, session_state})","d":"Menjalankan aplikasi Slak secara tersembunyi untuk diuji, seperti **AppTest** di Streamlit. Hasilnya objek uji `at`: elemen per jenis (`at.title`, `at.metric(\"Omzet\")`, `at.button(\"Kirim\")`, `at.write[0].value`), `at.session_state`, `at.exception`, `at.text_content`. Isi widget dengan `.set_value(nilai)`, tekan tombol dengan `.click()`, lalu jalankan ulang dengan `await ... .run()`. Tutup dengan `at.close()`.","ns":"testing","k":"// Aplikasi yang diuji (biasanya disimpan sebagai berkas .slak sendiri)\nconst kode = `\nconst harga = sl.number_input(\"Harga\", { value: 100000 })\nconst diskon = sl.slider(\"Diskon (%)\", 0, 50, 10)\nsl.metric(\"Bayar\", harga * (100 - diskon) / 100)\n`\nconst at = await sl.testing.run(kode)\nsl.write(\"Bayar awal:\", at.metric(\"Bayar\").value)          // 90000\nawait at.slider(\"Diskon (%)\").set_value(25).run()          // geser slider, jalankan ulang\nsl.write(\"Bayar sesudah diskon 25%:\", at.metric(\"Bayar\").value)\nat.close()"},{"g":"Uji aplikasi","n":"test","sig":"await testing.test(judul, async () => { ... })","d":"Uji bernama. Hasilnya tampil di aplikasi: kotak hijau bila lolos (dengan lama waktunya), kotak merah berisi pesan bila gagal. `sl.testing.summary()` menampilkan jumlah lolos dan gagal; `sl.testing.results` berisi daftar hasil.","ns":"testing","k":"const kode = `\nconst harga = sl.number_input(\"Harga\", { value: 100000 })\nconst diskon = sl.slider(\"Diskon (%)\", 0, 50, 10)\nsl.metric(\"Bayar\", harga * (100 - diskon) / 100)\n`\nawait sl.testing.test(\"harga awal didiskon 10%\", async () => {\n  const at = await sl.testing.run(kode)\n  sl.testing.expect(at.metric(\"Bayar\").value).toBe(90000)\n  at.close()\n})\nawait sl.testing.test(\"diskon 50% jadi setengah harga\", async () => {\n  const at = await sl.testing.run(kode)\n  await at.slider(\"Diskon (%)\").set_value(50).run()\n  sl.testing.expect(at.metric(\"Bayar\").value).toBe(50000)\n  at.close()\n})\nsl.testing.summary()"},{"g":"Uji aplikasi","n":"expect","sig":"testing.expect(nilai).toBe(x)","d":"Pernyataan untuk uji: `toBe`, `toEqual`, `toContain`, `toMatch`, `toBeGreaterThan`, `toBeLessThan`, `toBeCloseTo(x, desimal)`, `toHaveLength`, `toBeTruthy`, `toBeFalsy`, `toBeNull`, `toThrow`, dan kebalikannya lewat `.not` (misalnya `.not.toBe(0)`). Bila tidak cocok, melempar galat berbahasa Indonesia.","ns":"testing","k":"const { expect } = sl.testing\nawait sl.testing.test(\"pernyataan dasar\", async () => {\n  expect(1 + 1).toBe(2)\n  expect([1, 2, 3]).toContain(2)\n  expect(0.1 + 0.2).toBeCloseTo(0.3)\n  expect(\"Slak\").not.toBe(\"Streamlit\")\n})\nawait sl.testing.test(\"contoh yang sengaja gagal\", async () => {\n  expect(sl.dataset(\"penjualan\").length).toBeLessThan(10)\n})"},{"g":"Grafik","n":"pydeck_chart","sig":"pydeck_chart(spesifikasi, {height, tooltip, map_style})","d":"Peta 3D dan peta data besar dengan **deck.gl**, padanan `st.pydeck_chart`. Spesifikasinya JSON deck.gl, sama dengan hasil `pydeck.Deck.to_json()`: `initialViewState`, `layers` dengan `\"@@type\": \"HexagonLayer\"` dan sebagainya, akses kolom dengan `\"@@=nama_kolom\"`. Kolom `data` boleh DataFrame. Peta dasar OpenStreetMap tanpa kunci API (`map_style: null` untuk mematikan). deck.gl dimuat dari internet saat pertama dipakai.","k":"// Titik penjualan per kota, tinggi kolom = omzet (butuh internet untuk deck.gl dan peta dasar)\nconst kota = sl.DataFrame({\n  kota: [\"Jakarta\", \"Surabaya\", \"Medan\", \"Makassar\", \"Jayapura\"],\n  lon: [106.85, 112.75, 98.67, 119.43, 140.72], lat: [-6.21, -7.25, 3.59, -5.14, -2.53],\n  omzet: [950, 620, 410, 300, 180]\n})\nsl.pydeck_chart({\n  initialViewState: { longitude: 120, latitude: -2, zoom: 3.3, pitch: 40 },\n  layers: [{ \"@@type\": \"ColumnLayer\", data: kota, getPosition: \"@@=[lon, lat]\", getElevation: \"@@=omzet * 1000\",\n             radius: 40000, getFillColor: [15, 118, 110], pickable: true }]\n}, { tooltip: { text: \"{kota}: Rp{omzet} juta\" } })","online":1},{"g":"SQL & Python","n":"secrets","sig":"secrets","d":"Sengaja **tidak tersedia**. Halaman Slak dikirim utuh ke browser pengunjung, jadi rahasia di dalamnya bisa dibaca siapa saja. Simpan password database dan kunci API di **slak-bridge.php** atau **slak-bridge.js** di server, lalu baca datanya lewat `sl.connection(..., {type: \"bridge\"})` (Bab 33). Membaca `sl.secrets[\"x\"]` menampilkan pesan yang menjelaskan hal ini.","k":"// sl.secrets sengaja tidak ada: semua isi halaman Slak bisa dibaca pengunjung\ntry {\n  const kunci = sl.secrets[\"DB_PASSWORD\"]\n} catch (e) {\n  sl.info(e.message)\n}"},{"g":"Komponen","n":"component","sig":"component(html | \"folder/index.html\", {args, key, default, height})","d":"Widget buatan sendiri dari HTML dan JavaScript, berjalan di bingkai terpisah. Di dalam HTML tersedia `Slak.component.args` (data dari Slak), `Slak.component.onRender(fn)` (dipanggil setiap args berubah), `Slak.component.setValue(nilai)` (mengirim nilai kembali; aplikasi dijalankan ulang dan `sl.component(...)` mengembalikan nilai itu), `Slak.component.setHeight(px)`, dan `Slak.component.theme`. Tingginya menyesuaikan isi bila `height` tidak diisi. Objek `Streamlit` (setComponentValue, setFrameHeight, events) juga tersedia, sehingga kode komponen Streamlit tanpa pustaka bisa disalin.","k":"// Tombol penghitung buatan sendiri: nilainya kembali ke Slak\nconst hitung = sl.component(`\n<button id=\"b\" style=\"font: 16px sans-serif; padding: 6px 14px\">Tambah</button>\n<script>\n  let n = 0\n  Slak.component.onRender(args => { n = args.mulai })\n  document.getElementById(\"b\").onclick = () => Slak.component.setValue(++n)\n<\\/script>`, { args: { mulai: 0 }, key: \"hitung\", default: 0 })\nsl.metric(\"Sudah diklik\", hitung)"},{"g":"Komponen","n":"declare_component","sig":"components.declare_component(nama, {url})","d":"Memakai komponen yang sudah jadi dari folder, termasuk folder **build/** komponen Streamlit (berisi index.html). Hasilnya fungsi: `const bintang = sl.components.declare_component(\"bintang\", { url: \"bintang\" })`, lalu `bintang({ label: \"Nilai\", key: \"r\", default: 3 })`. Seperti Streamlit, `key`, `default`, dan `on_change` dipakai Slak, sisanya dikirim ke komponen sebagai args. Taruh foldernya di samping berkas .slak atau halaman HTML. Tabel Arrow (DataFrame dari komponen) belum didukung; kirim daftar objek.","ns":"components","k":"// Komponen dari folder (misalnya folder build/ komponen Streamlit) di samping berkas .slak:\n//   bintang/index.html\n// Contoh ini memakai HTML langsung agar bisa dicoba tanpa folder.\nconst bintang = sl.components.declare_component(\"bintang\", { html: `\n<div id=\"s\" style=\"font-size: 28px; cursor: pointer\"></div>\n<script>\n  Slak.component.onRender(a => {\n    const s = document.getElementById(\"s\"); s.innerHTML = \"\"\n    for (let i = 1; i <= a.maks; i++) { const b = document.createElement(\"span\"); b.textContent = i <= a.nilai ? \"★\" : \"☆\"; b.onclick = () => Slak.component.setValue(i); s.append(b) }\n  })\n<\\/script>` })\nconst nilai = bintang({ maks: 5, nilai: sl.session_state.r || 3, key: \"r\", default: 3 })\nsl.write(\"Nilai:\", nilai)"},{"g":"Komponen","n":"html","sig":"components.html(html, {height})","d":"Padanan `st.components.v1.html`: menampilkan HTML di bingkai, tanpa nilai kembali. Tinggi bawaan 150 piksel.","ns":"components","k":"sl.html('<div style=\"padding:12px;border-radius:10px;background:#ecfdf5;color:#065f46\">Kotak <b>HTML</b> sendiri</div>')"},{"g":"Slak Data","n":"ml_demo","sig":"ml_demo(model, df, {target, features, labels, title, key, explain})","d":"Formulir **coba model**: setiap fitur mendapat widget yang sesuai (slider untuk angka, pilihan untuk teks, kotak centang untuk ya/tidak), lalu prediksinya tampil langsung. Untuk klasifikasi juga tampil peluang tiap kelas. Model yang belum dilatih dilatih otomatis bila `target` diisi. `labels` memberi nama kelas, misalnya `{ 0: \"Bertahan\", 1: \"Berhenti\" }`. `explain: false` menyembunyikan bagian fitur paling berpengaruh. Mengembalikan `{ input, prediction, proba }`.","k":"// Model dilatih otomatis dari data, lalu bisa dicoba dengan menggeser nilai\nconst df = sl.dataset(\"pelanggan\").drop(\"pelanggan_id\")\nconst hasil = sl.ml_demo(sl.ml.DecisionTreeClassifier({ max_depth: 4 }), df,\n  { target: \"churn\", labels: { 0: \"Bertahan\", 1: \"Berhenti\" } })\nsl.caption(\"Masukan saat ini: \" + JSON.stringify(hasil.input))"},{"g":"SQL & Python","n":"report","sig":"await report(markdown | \"laporan.md\", {tables, db, params, show_sql})","d":"Laporan Markdown dengan blok ```sql yang dijalankan. Tabel dari `tables` (DataFrame, butuh slak-sql.js) atau `db` (sl.sqlite, sl.connection). Opsi di baris pembuka blok: `name=ringkas`, `chart=bar|line|area|scatter|pie`, `x=kota y=omzet`, `format=rp`, `show=table|chart|both`, `hide` (jalankan tanpa menampilkan), `code` (tampilkan SQL-nya), `title=\"Judul\"`, `height=240`. Di teks, `{{ ringkas.omzet | rp }}` diganti nilai baris pertama; format: `rp`, `persen`, `0`–`9` (angka desimal), `tanggal`. `{{ nama.length }}` = jumlah baris. Mengembalikan semua hasil bernama.","k":"// Teks Markdown biasa; blok sql dijalankan dan hasilnya ditampilkan\nawait sl.report(`\n# Ringkasan Penjualan\n\nAda **{{ ringkas.transaksi }} transaksi** dengan omzet **{{ ringkas.omzet | rp }}**.\nKota terbesar: **{{ kota.kota }}** ({{ kota.porsi | persen }}).\n\n\\`\\`\\`sql name=ringkas hide\nSELECT COUNT(*) AS transaksi, SUM(total) AS omzet FROM penjualan\n\\`\\`\\`\n\n\\`\\`\\`sql name=kota chart=bar x=kota y=omzet format=rp code\nSELECT kota, SUM(total) AS omzet, SUM(total) * 1.0 / (SELECT SUM(total) FROM penjualan) AS porsi\nFROM penjualan GROUP BY kota ORDER BY omzet DESC\n\\`\\`\\`\n`, { tables: { penjualan: sl.dataset(\"penjualan\") } })"},{"g":"Login & pengguna","n":"login","sig":"await login({bridge: db, title, remember})","d":"Login yang diperiksa di server lewat **slak-bridge** (bagian `users` atau `users_query`). Password tidak pernah ada di halaman. Setelah masuk, permintaan ke `db` membawa token, sehingga kueri bernama dengan `role` dan `:_user` (diisi nama pengguna yang masuk) bisa dipakai, misalnya \"nilai saya\". `sl.user`, `sl.require_role`, dan `sl.logout` bekerja seperti login lokal.","k":"const user = await sl.login({\n  users: {\n    ani:  { password: \"$2y$10$qlFsqVOQ2Fg.JoyEeObqGuxcui98Wciz2a5XQWUPHSKXffI4ng3sy\", name: \"Ani\", role: \"admin\" },   // password: rahasia\n    budi: { password: \"$2y$10$1CqnlJsbMyNlswHM.h5IJO3XSrqx5dBpnknnMT4Sb/2wV/yyP0uEa\", name: \"Budi\", role: \"kasir\" }  // password: admin123\n  },\n  title: \":convenience_store: Toko Maju\"\n})\nsl.success(`Selamat datang, ${user.name}!`)"},{"g":"SQL & Python","n":"connection","sig":"await db.check_quiz(nama, jawaban)","d":"Memeriksa jawaban kuis dengan kunci jawaban yang disimpan di slak-bridge (bagian `quizzes`), jadi kunci jawaban tidak terlihat di kode halaman. Hasilnya `{ score, total, percent, results: { s1: true, ... } }`, plus `answers` bila `show_answers` aktif. Jawaban dibandingkan tanpa membedakan huruf besar kecil dan spasi; angka boleh memakai koma (3,14). Bila `save_to` diisi, hasil disimpan ke tabel; `attempts` membatasi jumlah percobaan per pengguna.","k":"const conn = sl.connection(\"contoh_toko\", { type: \"sql\" })\nconst db = await conn.session\ndb.run(\"CREATE TABLE IF NOT EXISTS barang (nama TEXT, stok INT)\")\nif (!db.query(\"SELECT COUNT(*) n FROM barang\").n.values[0]) db.run(\"INSERT INTO barang VALUES ('Kopi', 12), ('Teh', 3)\")\nsl.dataframe(await conn.query(\"SELECT * FROM barang WHERE stok < :batas\", { params: { batas: 5 } }))"},{"g":"Slak 1.7","n":"share","sig":"share.link(kode, alamat_playground)","d":"Membuat **tautan berbagi**: kode dimampatkan ke bagian `#kode=…` alamat playground.html, sehingga tidak dikirim ke server mana pun. `await Slak.share.read(location.hash)` membaca kembali kodenya. Di Slak Studio: menu Berkas › Salin tautan berbagi. Di playground.html: tombol 🔗 Bagikan.","ns":"Slak","k":"// Buat tautan berbagi untuk kode di bawah, lalu baca kembali\nconst kode = 'sl.title(\"Halo dari tautan\")\\nsl.balloons()'\nconst link = await Slak.share.link(kode)   // bawaan: https://slak.studio/playground/\nsl.code(link, { language: \"text\", wrap_lines: true })\nsl.write(\"Panjang tautan:\", link.length, \"karakter\")\nsl.write(\"Dibaca kembali sama:\", (await Slak.share.read(link)) === kode)"},{"g":"Slak 1.7","n":"// %%","sig":"// %% Judul sel","d":"Mode sel di Slak Studio. Baris `// %%` membagi kode menjadi sel. Saat dijalankan ulang, sel yang **tidak berubah** dan berada di atas sel yang diubah tidak dijalankan lagi: variabel dan tampilannya diambil dari simpanan (cache). Sel yang diubah dan semua sel di bawahnya dijalankan ulang. Baris status menulis berapa sel dipakai ulang. Sel yang memakai widget, formulir, `session_state`, `Math.random`, atau waktu sekarang selalu dijalankan ulang. **Shift+Enter** menjalankan sampai akhir sel tempat kursor berada; tombol ▶ Sel di baris pemisah melakukan hal yang sama. Tombol Muat ulang mengosongkan simpanan. Di luar Slak Studio, baris itu hanya komentar.","ns":"Studio","s":"// %% Muat data"},{"g":"Tata letak","n":"layout","sig":"layout(nama, {title, caption})","d":"Kerangka halaman siap pakai yang mengembalikan **area bernama**. Isi area seperti mengisi kolom: `area.kpi.metric(...)`, `area.grafik.bar_chart(...)`. Pilihan: **\"kpi-atas\"** (area `kpi`, `grafik`, `tabel`; metrik di `kpi` tampil sebagai kartu sejajar), **\"sidebar-filter\"** (`filter` di sidebar, `kpi`, `grafik`, `tabel`), **\"grid-2x2\"** (`kpi`, `kiri_atas`, `kanan_atas`, `kiri_bawah`, `kanan_bawah`; di layar sempit menjadi satu kolom), dan **\"laporan\"** (`judul`, `ringkasan`, `isi`, `catatan`; satu kolom, nyaman dicetak). Di Slak Studio: Berkas › Baru dari templat.","k":"const df = sl.dataset(\"penjualan\")\nconst area = sl.layout(\"kpi-atas\", { title: \"📊 Dasbor Penjualan\" })\narea.kpi.metric(\"Omzet\", df.total.sum(), null, { format: \"rp\" })\narea.kpi.metric(\"Transaksi\", df.length)\narea.kpi.metric(\"Kota\", df.kota.nunique())\nconst perKota = df.groupby(\"kota\").agg({ omzet: [\"total\", \"sum\"] })\narea.grafik.bar_chart(perKota, { x: \"kota\", y: \"omzet\", format: \"rp\" })\narea.tabel.dataframe(perKota, { hide_index: true })"},{"g":"Uji aplikasi","n":"from_string","sig":"testing.from_string(kode) · from_file(\"berkas.slak\") · from_function(fungsi)","d":"Membuat objek uji tanpa langsung menjalankannya, seperti `AppTest.from_string`, `from_file`, dan `from_function` di Streamlit. Jalankan dengan `await at.run()`. `from_file` membaca berkas di folder yang sama (di Studio) atau berkas yang dipilih di slak-test.html.","ns":"testing","k":"const at = sl.testing.from_string(`\nconst n = sl.number_input(\"Jumlah\", { value: 2 })\nsl.metric(\"Total\", n * 15000)\n`)\nawait at.run()\nsl.write(\"Total awal:\", at.metric(\"Total\").value)        // 30000\nawait at.number_input(\"Jumlah\").set_value(4).run()\nsl.write(\"Total untuk 4:\", at.metric(\"Total\").value)     // 60000\nat.close()"},{"g":"Slak 1.7","n":"Panel Uji","sig":"nama.uji.slak","d":"Panel **Uji** di Slak Studio (rel kiri) menjalankan semua berkas `*.uji.slak` di folder berkas aktif dan merangkum yang lulus dan gagal. **Uji cepat** menjalankan berkas aktif dan memastikan tidak ada galat; **Buat berkas uji** membuat kerangka `nama.uji.slak` untuk aplikasi yang sedang dibuka. Di luar Studio, buka **slak-test.html** dari paket Slak.","ns":"Studio","s":"kasir.uji.slak"},{"g":"Slak 1.8","n":"Terbitkan","sig":"Berkas › Terbitkan… (Ctrl+Shift+U)","d":"Menerbitkan aplikasi ke **GitHub Pages**, **Netlify**, atau hosting **cPanel lewat FTP/FTPS** dengan sekali klik. Isinya sama dengan Ekspor folder situs (halaman, pustaka, data, folder komponen, PWA). Token dan password disimpan terenkripsi di komputer ini dan tidak pernah ikut ke situs; terbit dibatalkan bila token ditemukan di kode. GitHub: repositori dibuat dan Pages diaktifkan otomatis. Netlify: situs dibuat bila belum ada. FTP: hanya berkas yang berubah yang diunggah. Bisa juga menerbitkan sebuah folder, misalnya paket Slak sebagai situs playground.","ns":"Studio","s":"Berkas › Terbitkan…"},{"g":"Slak 1.8","n":"PWA","sig":"Ekspor folder situs / Terbitkan","d":"Situs hasil ekspor bisa **dipasang seperti aplikasi** dan tetap terbuka **tanpa internet** setelah kunjungan pertama: Slak Studio menambahkan `manifest.webmanifest`, `sw.js`, dan ikon 192/512 px dari `page_icon`. Hanya aktif di alamat https atau localhost; saat dibuka dengan klik dua kali, fitur ini tidur. Matikan lewat kotak centang di jendela Terbitkan.","ns":"Studio","s":"sl.set_page_config({ page_title: \"Toko Kopi\", page_icon: \"☕\" })"},{"g":"Slak 1.8","n":"BigQuery","sig":"Database › Koneksi baru › Google BigQuery","d":"Menjelajah dan menjalankan SQL di **Google BigQuery** dengan kunci JSON service account (peran BigQuery Job User dan Data Viewer). Dataset tampil sebagai skema, termasuk dataset publik seperti `bigquery-public-data.samples`. Sebelum kueri dijalankan, Studio memperkirakan byte yang diproses dan meminta konfirmasi di atas 1 GB; batas per kueri bisa diatur. Untuk aplikasi Slak, pakai lewat slak-bridge dengan `type: \"bigquery\"` supaya kunci tetap di server.","ns":"Studio","s":"'gudang' => ['type' => 'bigquery', 'key_file' => '...', 'max_gb' => 10]"},{"g":"Slak 1.8","n":"share.official","sig":"Slak.share.official","d":"Alamat playground resmi: `https://slak.studio/playground/` (sejak 1.9.1). `Slak.share.link(kode)` tanpa alamat memakai halaman ini bila dibuka lewat http(s), selain itu (Slak Studio, klik dua kali) memakai alamat resmi. Salinan resmi dengan format tautan yang sama: `https://slakstudio.github.io/playground/`. Paket Slak siap diunggah sebagai situs: lihat TERBIT-SITUS.md.","ns":"Slak","s":"sl.write(Slak.share.official)"},{"g":"Slak 1.8","n":"Cek jawaban","sig":"Pelajaran › Cek jawaban","d":"Untuk pelajaran yang butuh interaksi (menyalakan toggle, mengirim form, mengetik chat, memilih radio, membuka halaman), pemeriksa kini **mencobanya sendiri dengan sl.testing** bila kamu belum mencobanya di pratinjau. Judul uji yang gagal menjadi petunjuk.","ns":"Studio","s":"await at.toggle[0].set_value(true).run()"},{"g":"SQL & Python","n":"connection","sig":"connection(nama, { type: \"bridge\", database: \"gudang\" })","d":"Sejak 1.8, slak-bridge.php dan slak-bridge.js juga bisa terhubung ke **Google BigQuery** (`type: \"bigquery\"` di pengaturan jembatan, kunci JSON disimpan di server). Parameter bernama `:nama` diubah otomatis menjadi parameter BigQuery `@nama`, dan `max_gb` membatasi byte per kueri.","k":"const conn = sl.connection(\"contoh_toko\", { type: \"sql\" })\nconst db = await conn.session\ndb.run(\"CREATE TABLE IF NOT EXISTS barang (nama TEXT, stok INT)\")\nif (!db.query(\"SELECT COUNT(*) n FROM barang\").n.values[0]) db.run(\"INSERT INTO barang VALUES ('Kopi', 12), ('Teh', 3)\")\nsl.dataframe(await conn.query(\"SELECT * FROM barang WHERE stok < :batas\", { params: { batas: 5 } }))"},{"g":"Slak 1.9","n":"worker","sig":"await worker(fungsi, ...data)","d":"Menjalankan hitungan berat di **Web Worker** (utas latar), sehingga halaman tidak membeku. Fungsinya dikirim sebagai teks, jadi **tidak boleh memakai variabel dari luar dirinya** (termasuk `sl`): kirim semua yang dibutuhkan sebagai argumen. DataFrame dikirim sebagai daftar objek; ubah hasilnya kembali dengan `sl.DataFrame(hasil)`. Bila browser menolak worker, fungsi dijalankan biasa. Berlabel eksperimental di 1.9.","k":"// Hitungan berat di latar: halaman tetap bisa diklik\nconst t0 = performance.now()\nconst jumlah = await sl.worker((n, k) => { let s = 0; for (let i = 0; i < n; i++) s += i % k; return s }, 2e7, 7)\nsl.metric(\"Hasil\", jumlah)\nsl.caption(\"Selesai dalam \" + Math.round(performance.now() - t0) + \" md di Web Worker\")\n\n// DataFrame dikirim sebagai daftar objek\nconst df = sl.dataset(\"penjualan\")\nconst besar = await sl.worker((rows) => rows.filter(r => r.total > 500000), df)\nsl.dataframe(sl.DataFrame(besar).head(5))"},{"g":"Slak 1.9","n":"read_csv besar","sig":"await read_csv(sumber, { worker })","d":"Sejak 1.9, CSV di atas 5 MB diurai di Web Worker secara otomatis: pemotongan teks, penanda kosong, angka, ya/tidak, dan tanggal ISO dikerjakan di latar. Hasilnya sama persis dengan jalur biasa. Pada CSV 26 MB, halaman membeku sekitar 0,2 detik saja (sebelumnya 0,8 detik). `worker: false` mematikannya; `worker: true` memakainya untuk berkas kecil juga.","ns":"Slak Data","s":"const df = await sl.read_csv(\"besar.csv\")"},{"g":"Slak 1.9","n":"Aksesibilitas","sig":"(otomatis)","d":"Widget punya nama untuk pembaca layar (diambil dari labelnya, juga saat `label_visibility: \"collapsed\"`), semua kontrol bisa dicapai dengan Tab dan punya garis fokus, tabel bisa digulir dengan papan ketik, toast diumumkan, dan grafik punya teks pengganti otomatis seperti \"Grafik omzet menurut kota, 6 titik\". Isi opsi `alt` atau `title` pada grafik untuk teks yang lebih jelas. Warna teks memenuhi kontras WCAG AA.","ns":"Slak","s":"sl.bar_chart(df, { x: \"kota\", y: \"omzet\", alt: \"Omzet tertinggi di Jayapura\" })"},{"g":"Slak 1.9","n":"API-STABIL.md","sig":"API-STABIL.md · KEBIJAKAN-VERSI.md","d":"938 nama API (perintah `sl.*`, `Slak.*`, metode DataFrame dan Series) **dijamin tetap ada sampai Slak 2.0**. Fungsi baru boleh ditambahkan pada 1.9.x, tetapi yang ada tidak dihapus atau diubah artinya.","ns":"Slak","s":"sl.version   // \"1.9.0\""},{"g":"Slak 1.9","n":"old_names","sig":"Slak.old_names","d":"Nama lama Streamlit tetap bekerja dengan peringatan sekali di konsol: `experimental_rerun`, `experimental_dialog`, `experimental_fragment`, `experimental_get_query_params`, `experimental_set_query_params`, `cache`, `experimental_memo`, `experimental_singleton`, `beta_columns`, `beta_expander`, `beta_container`, `beta_tabs`. `Slak.old_names` berisi pasangan nama lama dan nama barunya.","ns":"Slak","k":"// Nama lama Streamlit tetap bekerja (peringatan sekali di konsol)\nconst [kiri, kanan] = sl.beta_columns(2)\nkiri.metric(\"Kiri\", 1)\nkanan.metric(\"Kanan\", 2)\nsl.write(Slak.old_names)"},{"g":"Slak 1.9.1","n":"docs.site","sig":"await Slak.docs.site(sl, { judul, bab, kaki, playground })","d":"Butuh **slak-docs.js** (versi 0.1, eksperimental; tersedia otomatis di Slak Studio). Satu panggilan untuk seluruh situs dokumentasi: menu berkelompok di sidebar, alamat per halaman (`#/alamat`), tombol Sebelumnya/Berikutnya, daftar isi, dan pencarian Ctrl+K. Setiap bab berisi `judul` dan salah satu dari `isi` (teks Markdown), `elemen` (id blok `<script type=\"text/markdown\">` di halaman), `berkas` (berkas .md, hanya lewat hosting), atau `fungsi` (`(sl) => {...}`). Fungsi Slak.docs tidak menambah nama ke `sl`.","ns":"Slak","s":"await Slak.docs.site(sl, { judul: \"Panduanku\", bab: { \"Mulai\": [\n  { judul: \"Halo\", isi: \"## Sapaan\\n\\nSelamat datang.\" },\n  { judul: \"Contoh\", isi: \"## Coba\\n\\n```slak\\nsl.metric(\\\"Jawaban\\\", 42)\\n```\" }\n] } })"},{"g":"Slak 1.9.1","n":"docs.markdown","sig":"await Slak.docs.markdown(sl, teks, { playground })","d":"Menampilkan isi bab dari Markdown. Judul `#`, `##`, `###` menjadi `sl.title`, `sl.header`, `sl.subheader` dengan jangkar. Blok kode berbahasa `slak` dijalankan di dalam kotak di bawah kodenya, dengan tautan **Buka di Playground**; tulis `slak tanpa-jalan` untuk hanya menampilkan kode. Contoh berbagi halaman dengan bab, jadi contoh yang memakai `sl.navigation`, `sl.set_page_config`, atau `sl.stop` sebaiknya `tanpa-jalan`. Mengembalikan daftar judul.","ns":"Slak","k":"// Butuh slak-docs.js (1.9.1). Blok slak dijalankan, hasilnya tampil di bawah kodenya.\nawait Slak.docs.markdown(sl, `## Kalkulator kecil\n\nGeser penggesernya:\n\n\\`\\`\\`slak\nconst n = sl.slider(\"Angka\", 1, 10, 4)\nsl.metric(\"Kuadrat\", n * n)\n\\`\\`\\``, { playground: false })"},{"g":"Slak 1.9.1","n":"docs.toc","sig":"Slak.docs.toc(sl, { where, label })","d":"Daftar isi \"Di halaman ini\" dari judul tingkat 2 dan 3 bab terakhir yang ditampilkan dengan `Slak.docs.markdown`. Bawaannya di sidebar; bagian yang sedang dibaca ditandai saat halaman digulir.","ns":"Slak","s":"await Slak.docs.markdown(sl, \"## Satu\\n\\nA\\n\\n## Dua\\n\\nB\", { playground: false })\nSlak.docs.toc(sl, { where: sl })"},{"g":"Slak 1.9.1","n":"docs.search","sig":"Slak.docs.search(sl, halaman)","d":"Tombol **Cari (Ctrl+K)** yang membuka dialog pencarian di seluruh halaman. `halaman` berisi `{ judul, teks, halaman }` (objek dari `sl.page` untuk tautan). `Slak.docs.site` memasangnya otomatis.","ns":"Slak","s":"Slak.docs.search(sl, [{ judul: \"Grafik\", teks: \"## Batang\\n\\nsl.bar_chart menggambar grafik batang.\" }], { where: sl })"},{"g":"Slak 1.9.1","n":"docs.meta","sig":"Slak.docs.meta({ judul, deskripsi, gambar, kanonik })","d":"Menulis deskripsi, gambar pratinjau (Open Graph), dan alamat kanonik ke `<head>`. Saat dibuka lewat http(s), alamat kanonik bawaannya halaman yang sama di **slak.studio**, sehingga salinan resmi slakstudio.github.io tidak dihitung sebagai isi ganda. WhatsApp, X, dan LinkedIn tidak menjalankan JavaScript; untuk pratinjau tautan per bab pakai `docs/TEMPLAT-BAB.html`.","ns":"Slak","s":"sl.json(Slak.docs.meta({ deskripsi: \"Panduan Slak\", kanonik: false }))"},{"g":"Slak 1.9.1","n":"Situs resmi","sig":"https://slak.studio · https://slakstudio.github.io","d":"Alamat resmi Slak adalah **slak.studio**, dengan salinan resmi **slakstudio.github.io** yang isinya sama. Playground pindah ke `playground/`; `playground.html` mengalihkan tautan lama. `Slak.share.official` kini `https://slak.studio/playground/`, dan **Berkas › Salin tautan berbagi** memakainya sebagai bawaan. Terbitkan › GitHub Pages mempertahankan berkas `CNAME` di repositori. Langkah menerbitkan ada di TERBIT-SITUS.md paket Slak.","ns":"Slak","k":"// Slak 1.9.1: playground resmi dan salinannya\nsl.write(\"Playground resmi:\", Slak.share.official)\nconst link = await Slak.share.link('sl.title(\"Halo\")')\nsl.code(link, { language: \"text\", wrap_lines: true })"}];
